IST_PNL = ZoneInfo('Asia/Kolkata')

def _pnl_number(row, *keys):
    for key in keys:
        value = row.get(key) if isinstance(row, dict) else None
        if value in (None, ''):
            continue
        try:
            return float(str(value).replace(',', '').replace('₹', '').strip())
        except (TypeError, ValueError):
            continue
    return None

def _pnl_rows(response):
    if not isinstance(response, dict):
        return []
    result = response.get('Success')
    return result if isinstance(result, list) else []

def _pnl_utc_iso(value: datetime) -> str:
    from datetime import timezone
    return value.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.000Z')

def fetch_breeze_account_pnl(breeze, now: datetime | None = None) -> dict:
    from datetime import time as dtime
    now = now or datetime.now(IST_PNL)
    if now.tzinfo is None:
        now = now.replace(tzinfo=IST_PNL)
    local_now = now.astimezone(IST_PNL)
    start = datetime.combine(local_now.date(), dtime.min, tzinfo=IST_PNL)
    from_date, to_date = _pnl_utc_iso(start), _pnl_utc_iso(local_now)

    portfolio_rows = []
    errors = []
    holdings_method = getattr(breeze, 'get_portfolio_holdings', None)
    if callable(holdings_method):
        for exchange in ('NSE', 'NFO'):
            try:
                response = holdings_method(
                    exchange_code=exchange,
                    from_date=from_date,
                    to_date=to_date,
                    stock_code='',
                    portfolio_type='',
                )
                portfolio_rows.extend(
                    row for row in _pnl_rows(response) if isinstance(row, dict)
                )
                if isinstance(response, dict) and response.get('Error'):
                    errors.append(f'{exchange} holdings: {response.get("Error")}')
            except Exception as exc:
                errors.append(f'{exchange} holdings: {type(exc).__name__}: {exc}')
    else:
        errors.append('Breeze SDK does not expose get_portfolio_holdings')

    positions = []
    positions_method = getattr(breeze, 'get_portfolio_positions', None)
    if callable(positions_method):
        try:
            positions_response = positions_method()
            positions = [r for r in _pnl_rows(positions_response) if isinstance(r, dict)]
            if isinstance(positions_response, dict) and positions_response.get('Error'):
                errors.append(f'Positions: {positions_response.get("Error")}')
        except Exception as exc:
            errors.append(f'Positions: {type(exc).__name__}: {exc}')
    else:
        errors.append('Breeze SDK does not expose get_portfolio_positions')

    def sum_reported(rows, keys):
        values = [_pnl_number(row, *keys) for row in rows]
        present = [value for value in values if value is not None]
        return round(sum(present), 2) if present else None

    realised = sum_reported(portfolio_rows, ('realized_profit', 'booked_profit_loss'))
    unrealised = sum_reported(portfolio_rows, ('unrealized_profit', 'unrealized_profit_loss'))
    charges = sum_reported(portfolio_rows, ('portfolio_charges', 'total_charges'))

    if unrealised is None and positions:
        unrealised = sum_reported(positions, ('pnl', 'unrealized_profit', 'unrealized_pnl'))

    detail_rows = []
    for row in positions:
        qty = _pnl_number(row, 'net_quantity', 'net_qty', 'quantity', 'open_quantity')
        if qty in (None, 0):
            continue
        symbol = str(row.get('stock_code') or row.get('symbol') or row.get('short_name') or '').strip()
        if not symbol:
            continue
        detail_rows.append({
            'symbol': symbol,
            'exchange': str(row.get('exchange_code') or ''),
            'product': str(row.get('product_type') or ''),
            'quantity': qty,
            'average_price': _pnl_number(row, 'average_price', 'avg_price', 'price'),
            'ltp': _pnl_number(row, 'ltp', 'last_traded_price', 'market_price'),
            'pnl': _pnl_number(row, 'pnl', 'unrealized_profit', 'unrealized_pnl'),
        })

    return {
        'as_of_date': local_now.date().isoformat(),
        'refreshed_at': local_now.strftime('%Y-%m-%d %H:%M:%S IST'),
        'realised': realised,
        'unrealised': unrealised,
        'charges': charges,
        'combined_reported': round(realised + unrealised, 2) if realised is not None and unrealised is not None else None,
        'positions': detail_rows,
        'portfolio_rows': len(portfolio_rows),
        'errors': errors,
        'source': 'ICICI Direct Breeze portfolioholdings / portfoliopositions',
    }

