# Self-contained QR support. The QR encoder is embedded so the user does not need
# to install the third-party qrcode package separately. The embedded library is
# unpacked only into the Windows TEMP directory at runtime.
_BUNDLED_QR_ZIP_B64 = ""

def _ensure_qr_support():
    try:
        import qrcode
        return qrcode
    except ImportError:
        pass
    tmp = Path(tempfile.gettempdir()) / 'BreezeNSE_QR_support_fixed.zip'
    if not tmp.exists():
        tmp.write_bytes(base64.b64decode(_BUNDLED_QR_ZIP_B64))
    if str(tmp) not in sys.path:
        sys.path.insert(0, str(tmp))
    importlib.invalidate_caches()
    for name in list(sys.modules):
        if name == 'qrcode' or name.startswith('qrcode.'):
            del sys.modules[name]
    import qrcode
    return qrcode

