class DataBlob(ctypes.Structure):
    _fields_=[('cbData',wintypes.DWORD),('pbData',ctypes.POINTER(ctypes.c_byte))]

def protect(data:bytes)->bytes:
    b=ctypes.create_string_buffer(data); src=DataBlob(len(data),ctypes.cast(b,ctypes.POINTER(ctypes.c_byte))); enc=DataBlob()
    if not ctypes.windll.crypt32.CryptProtectData(ctypes.byref(src),'Breeze credentials',None,None,None,CRYPTPROTECT_UI_FORBIDDEN,ctypes.byref(enc)): raise ctypes.WinError()
    try:return ctypes.string_at(enc.pbData,enc.cbData)
    finally:ctypes.windll.kernel32.LocalFree(enc.pbData)

def unprotect(data:bytes)->bytes:
    b=ctypes.create_string_buffer(data); src=DataBlob(len(data),ctypes.cast(b,ctypes.POINTER(ctypes.c_byte))); plain=DataBlob()
    if not ctypes.windll.crypt32.CryptUnprotectData(ctypes.byref(src),None,None,None,None,CRYPTPROTECT_UI_FORBIDDEN,ctypes.byref(plain)): raise ctypes.WinError()
    try:return ctypes.string_at(plain.pbData,plain.cbData)
    finally:ctypes.windll.kernel32.LocalFree(plain.pbData)

def parse_date(text:str):
    for fmt in ('%Y-%m-%d','%d-%m-%Y','%d/%m/%Y','%Y/%m/%d','%d-%b-%Y','%d %b %Y','%d-%B-%Y','%d/%m/%y'):
        try:return datetime.strptime(text.strip(),fmt).date()
        except ValueError: pass
    raise ValueError('Use a valid date such as 2026-09-17 or 17-Sep-2026.')

