    def _button_palette(self, label, bg):
        """Premium trading-terminal button hierarchy."""
        text=(label or '').upper()
        if 'SAFE STOP' in text or text.startswith('STOP') or 'AUTO SEND: OFF' in text:
            return ('#2A1820','#FF6B78','#3A2029','#571E2A')
        if 'LIVE' in text and ('START' in text or 'TRADING' in text):
            return ('#0B3B2B','#7BE7B0','#0F523A','#084A35')
        if 'PAPER' in text and ('START' in text or 'TRADING' in text):
            return ('#4A2B12','#FFB15C','#5B3516','#6D3E16')
        if any(x in text for x in ('BUY','PLACE ORDER','EXECUTE','START')):
            return ('#C45F0A','#FFFFFF','#E87514','#A84F08')
        if any(x in text for x in ('SELL','EXIT')):
            return ('#8E2935','#FFFFFF','#AA3543','#741F2B')
        if 'DOWNLOAD' in text or 'OPEN' in text or 'MOBILE' in text or 'APPLY' in text:
            return ('#152A43','#B9D7F5','#1A3554','#203F62')
        if 'SAVE' in text or 'TEST' in text or 'DIAGNOSTIC' in text:
            return ('#064E3B','#A7F3D0','#047857','#059669')
        if 'RESET' in text:
            return ('#1E293B','#E2E8F0','#334155','#475569')
        if 'CLEAR' in text:
            return ('#450A0A','#FCA5A5','#7F1D1D','#991B1B')
        return ('#0F1F31','#E2E8F0','#1E3A5F','#254E7E')

    def _pro_button(self, master=None, **kwargs):
        if master is None:
            master=self
        label=kwargs.get('text','')
        normal,fg,hover,active=self._button_palette(label, kwargs.get('bg'))
        kwargs['bg']=normal
        kwargs.setdefault('fg',fg)
        kwargs.setdefault('activeforeground', '#FFFFFF' if fg != '#FFFFFF' else '#FFFFFF')
        kwargs['activebackground']=active
        kwargs.setdefault('disabledforeground','#94A3B8')
        kwargs.setdefault('relief','flat')
        kwargs.setdefault('overrelief','flat')
        kwargs.setdefault('bd',0)
        kwargs.setdefault('highlightthickness',1)
        kwargs.setdefault('highlightbackground',self.BORDER)
        kwargs.setdefault('highlightcolor',self.ACCENT)
        kwargs.setdefault('cursor','hand2')
        kwargs.setdefault('font',('Segoe UI Semibold',9))
        kwargs.setdefault('padx',16)
        kwargs.setdefault('pady',9)
        btn=tk.Button(master,**kwargs)
        btn._terminal_normal=normal; btn._terminal_hover=hover; btn._terminal_active=active
        def enter(_):
            if btn['state']!='disabled': btn.configure(bg=hover,highlightbackground=self.ACCENT)
        def leave(_):
            if btn['state']!='disabled': btn.configure(bg=normal,highlightbackground=self.BORDER)
        def press(_):
            if btn['state']!='disabled': btn.configure(bg=active,highlightbackground=self.ACCENT_DARK)
