    def _schedule_ui(self, callback, delay=0):
        """Schedule a Tk callback that can be cancelled during application shutdown."""
        if self._closing:
            return None
        try:
            aid = self.after(delay, callback)
            self._after_ids.append(aid)
            return aid
        except Exception:
            return None

    def _safe_taskkill(self, pid):
        """Terminate a tracked child quickly without blocking GUI shutdown."""
        try:
            if pid and os.name == 'nt':
                subprocess.Popen(
                    ['taskkill', '/PID', str(pid), '/T', '/F'],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0)
                )
        except Exception:
            pass

    def _shutdown_remote_agent(self):
        """Best-effort, short-timeout shutdown of the mobile helper process."""
        if os.name != 'nt':
            return
        # Ask the helper to stop, but never wait several seconds for a response.
        try:
            cfg = json.loads(REMOTE_CONFIG.read_text(encoding='utf-8')) if REMOTE_CONFIG.exists() else {}
            token = str(cfg.get('token', '')).strip()
            port = int(cfg.get('active_port') or cfg.get('listen_port') or 8765)
            if token:
                req = urllib.request.Request(
                    f'http://127.0.0.1:{port}/shutdown?token={urllib.parse.quote(token, safe="")}',
                    data=b'', method='POST', headers={'X-Remote-Token': token})
                try:
                    with urllib.request.urlopen(req, timeout=0.4) as r:
                        r.read(256)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            rp = self._remote_agent_proc
            if rp is not None and rp.poll() is None:
                self._safe_taskkill(rp.pid)
        except Exception:
            pass
        self._remote_agent_proc = None

    def _force_stop_all_workers(self):
        """Quickly request termination of the worker process tracked by this GUI.

        Avoids blocking PowerShell process scans during window close.  The worker
        process tree is terminated by taskkill when a tracked process exists.
        """
        try:
            proc = self.proc
            if proc is not None and proc.poll() is None:
                self._safe_taskkill(proc.pid)
        except Exception:
            pass
        self.proc = None

    def _finish_window_close(self):
        """Finish GUI shutdown only after the tracked market engine has exited."""
        try:
            self._shutdown_remote_agent()
        except Exception:
            pass
        try:
            conn = self._market_breeze_conn
            self._market_breeze_conn = None
            if conn is not None:
                for name in ('ws_disconnect', 'disconnect', 'close'):
                    fn = getattr(conn, name, None)
                    if callable(fn):
                        try:
                            fn()
                        except Exception:
                            pass
                        break
        except Exception:
            pass
        try:
            self.destroy()
        except Exception:
            pass

    def _poll_close_shutdown(self):
        """Allow PAPER/LIVE cleanup to finish; force-stop only after 60 seconds."""
        proc = getattr(self, 'proc', None)
        starting = bool(getattr(self, '_process_starting', False))
        running = False
        try:
            running = proc is not None and proc.poll() is None
        except Exception:
            running = proc is not None

        if running or (starting and proc is None):
            elapsed = time.monotonic() - getattr(self, '_close_wait_started_at', time.monotonic())
            if elapsed >= 60.0:
                if not getattr(self, '_close_force_sent', False):
                    self._close_force_sent = True
                    try:
                        self.logline('WINDOW CLOSE: graceful shutdown exceeded 60s; force-stopping remaining process tree.')
                    except Exception:
                        pass
                    try:
                        if proc is not None and proc.poll() is None:
                            self._safe_taskkill(proc.pid)
                    except Exception:
                        pass
                # Give taskkill a moment to reap the process before destroying Tk.
                try:
                    self.after(1000, self._poll_close_shutdown)
                except Exception:
                    self._finish_window_close()
                return
            try:
                self.after(250, self._poll_close_shutdown)
            except Exception:
                # Tk is already unavailable; do not leave a known child running.
                try:
                    if proc is not None and proc.poll() is None:
                        self._safe_taskkill(proc.pid)
                except Exception:
                    pass
                self._finish_window_close()
            return

        self._finish_window_close()

    def _on_close(self):
        """Stop trading cleanly before closing the desktop application."""
        if self._closing:
            return
        self._closing = True
        try:
            self.status.set('Stopping trading safely before closing...')
        except Exception:
            pass
        try:
            self._set_auto_download_off()
        except Exception:
            pass
        try:
            self.market_stop.set()
            self.scanner_stop.set()
            self.smart_trade_stop.set()
        except Exception:
            pass
        try:
            self._stop_download_power_guard()
            self._keep_screen_on(False)
        except Exception:
            pass
        for aid in list(self._after_ids):
            try:
                self.after_cancel(aid)
            except Exception:
                pass
        self._after_ids.clear()
        try:
            self._stop_action_timer()
        except Exception:
            pass

        action = getattr(self, '_active_action_button', None)
        market_action = action in {'paper', 'live'}
        proc = getattr(self, 'proc', None)
        try:
            running = proc is not None and proc.poll() is None
        except Exception:
            running = proc is not None
        starting = bool(getattr(self, '_process_starting', False))

        if market_action and (running or starting):
            # BreezeTrading polls this same flag and performs its own orderly
            # unsubscribe, position/session cleanup and state persistence.
            try:
                REMOTE_STOP_FLAG.write_text('stop', encoding='utf-8')
                self.logline('WINDOW CLOSE: graceful PAPER/LIVE stop requested; waiting up to 60s for engine cleanup.')
            except Exception as exc:
                try:
                    self.logline(f'WINDOW CLOSE: stop flag could not be written: {type(exc).__name__}: {exc}')
                except Exception:
                    pass
        elif running:
            # Historical/download workers have no market cleanup protocol.
            try:
                self._safe_taskkill(proc.pid)
            except Exception:
                pass

        self._close_wait_started_at = time.monotonic()
        self._close_force_sent = False
        try:
            self.after(250, self._poll_close_shutdown)
        except Exception:
            # If Tk cannot schedule another callback, prefer a safe process-tree
            # stop over leaving a detached worker behind.
            try:
                if proc is not None and proc.poll() is None:
                    self._safe_taskkill(proc.pid)
            except Exception:
                pass
            self._finish_window_close()

