        def move_sidebar_item(key, offset):
            current_index = next((i for i, item in enumerate(sidebar_items) if item['key'] == key), -1)
            target_index = current_index + offset
            if current_index < 0 or target_index < 0 or target_index >= len(sidebar_items):
                return
            sidebar_items[current_index], sidebar_items[target_index] = sidebar_items[target_index], sidebar_items[current_index]
