            tk.Label(head,text=subtitle,bg='#14243A',fg='#7890A8',font=('Segoe UI',7)).pack(anchor='w',padx=9,pady=(0,6))
            frame=tk.Frame(box,bg='#0D1929'); frame.grid(row=1,column=0,sticky='nsew')
