    def _schedule_broker_account_pnl_refresh(self):
        if self._closing:
            return
        try:
            if all(v.get().strip() for v in (self.api_key,self.api_secret,self.session_token)):
                self.refresh_broker_account_pnl()
        except Exception:
            pass
        self._schedule_ui(self._schedule_broker_account_pnl_refresh, 300000)

    def refresh_broker_account_pnl(self):
        if not hasattr(self,'broker_pnl_status'):
            return
        self.broker_pnl_status.set('Fetching read-only Breeze account P&L…')
        threading.Thread(target=self._broker_account_pnl_worker,daemon=True,name='breeze-account-pnl').start()

    def _broker_account_pnl_worker(self):
        try:
            breeze=self._market_breeze()
            result=fetch_breeze_account_pnl(breeze)
            self._schedule_ui(lambda data=result:self._render_broker_account_pnl(data),0)
        except Exception as exc:
            message=f'{type(exc).__name__}: {exc}'[:220]
            self._schedule_ui(lambda msg=message:self.broker_pnl_status.set('Broker P&L unavailable: '+msg),0)

    def _render_broker_account_pnl(self, data):
        if not hasattr(self,'broker_pnl_status'):
            return
        def fmt(value):
            return '—' if value is None else f'₹{value:,.2f}'
        values={'realised':data.get('realised'),'unrealised':data.get('unrealised'),'charges':data.get('charges'),'combined':data.get('combined_reported')}
        for key,value in values.items():
            self.broker_pnl_vars[key].set(fmt(value))
        for item in self.broker_pnl_tree.get_children(''):
            self.broker_pnl_tree.delete(item)
        for row in data.get('positions',[]):
            self.broker_pnl_tree.insert('', 'end', values=(row.get('symbol',''),row.get('exchange',''),row.get('product',''),
                '—' if row.get('quantity') is None else f"{row['quantity']:,.2f}",
                '—' if row.get('average_price') is None else f"{row['average_price']:,.2f}",
                '—' if row.get('ltp') is None else f"{row['ltp']:,.2f}",fmt(row.get('pnl'))))
        errors=data.get('errors') or []
        suffix=(' • warnings: '+ '; '.join(errors[:2])) if errors else ''
        self.broker_pnl_status.set(f"{data.get('as_of_date')} • refreshed {data.get('refreshed_at')} • {len(data.get('positions',[]))} open positions • READ ONLY{suffix}")

    def _apply_toolbar_direction(self):
        val = str(self.logic_toolbar_direction_var.get()).upper()
        dir_code = 'UP' if 'UP' in val else ('DOWN' if 'DOWN' in val else 'BOTH')
        if hasattr(self, 'logic_vars') and 'Logic 1' in self.logic_vars:
            if 'open_direction' in self.logic_vars['Logic 1']:
                self.logic_vars['Logic 1']['open_direction'].set(dir_code)
        cfg = load_logics()
        if 'Logic 1' in cfg:
            cfg['Logic 1']['open_direction'] = dir_code
            save_logics(cfg)
        desc = '🟢 BUY ONLY (UP)' if dir_code == 'UP' else ('🔴 SELL SHORT (DOWN)' if dir_code == 'DOWN' else '🔵 BOTH (BUY & SELL)')
        self.status.set(f"Logic 1 Direction set to: {desc}")
        messagebox.showinfo("Trade Action Applied", f"Logic 1 Direction set to: {desc}\n\nClick 'Save' to persist all rows.")

    def _on_logic_toolbar_direction_changed(self, event=None):
        self._apply_toolbar_direction()

    def _on_market_direction_selected(self, event=None):
        val = str(self.market_direction_var.get()).upper()
        dir_code = 'UP' if 'UP' in val else ('DOWN' if 'DOWN' in val else 'BOTH')
        try:
            if hasattr(self, 'logic_vars') and 'Logic 1' in self.logic_vars:
                self.logic_vars['Logic 1']['open_direction'].set(dir_code)
                self._persist_current_gui_logic_settings(show_message=False)
            else:
                cfg = load_logics()
                if 'Logic 1' in cfg:
                    cfg['Logic 1']['open_direction'] = dir_code
                    save_logics(cfg)
            desc = '🟢 BUY ONLY (UP MARKET)' if dir_code == 'UP' else ('🔴 SELL SHORT (DOWN MARKET)' if dir_code == 'DOWN' else '🔵 BOTH (AUTO BI-DIRECTIONAL)')
            self.status.set(f'Day Start Trade Direction set: {desc} for Logic 1')
            messagebox.showinfo('Trade Direction Fixed', f'Logic 1 Direction set to: {desc}\n\nProgram will now automatically trade according to this direction all day.')
        except Exception as ex:
            messagebox.showerror('Direction Set Error', str(ex))

