    def _tick_live_clock(self):
        try:
            now=datetime.now().strftime('%H:%M:%S')
            self.live_clock_var.set(now)
            mode=str(self.pnl_mode_var.get() if hasattr(self,'pnl_mode_var') else 'IDLE').upper()
            self.nav_status_var.set(('● '+mode)[:30])
            if hasattr(self,'home_status_var'):
                self.home_status_var.set(mode)
                self.home_status_detail.set('Last GUI update: '+datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
            if hasattr(self,'smart_mode_var'):
                self.smart_mode_var.set(mode)
                try: self.smart_breeze_var.set('Breeze API: '+('CONNECTED' if self._market_breeze_conn is not None else 'READY'))
                except Exception: pass
                try: self.smart_wa_var.set('WhatsApp: ON' if self.wa_personal_enabled.get() else 'WhatsApp: OFF')
                except Exception: pass
                try: self.smart_hist_var.set('Historical: '+('RUNNING' if self.proc and self.proc.poll() is None else 'READY'))
                except Exception: pass
        except Exception:
            pass
        if not self._closing:
            self._schedule_ui(self._tick_live_clock,1000)

    def show_page(self, key):
        # Persist the visible Trading Logic table before opening the CSV calculator,
        # so the calculator cannot show stale values from an older config file.
        if key == 'csv_pnl':
            try:
                self._persist_current_gui_logic_settings(show_message=False)
                if hasattr(self, 'csv_pnl_app'):
                    self.csv_pnl_app.refresh_logic_summary()
            except Exception as exc:
                try:
                    self.status.set('Could not sync Trading Logic to calculator: ' + str(exc))
                except Exception:
                    pass
        # Hide all pages and explicitly raise the selected page. Historical Trading
        # is the default page and is also directly available from the sidebar.
        if key not in self.pages:
            key = 'historical'
        for frame in self.pages.values():
            try:
                frame.grid_remove()
            except tk.TclError:
                pass
        page = self.pages.get(key)
        if page is None:
            return
        page.grid(row=0, column=0, sticky='nsew')
        page.tkraise()
        self.canvas = self.page_canvases.get(key)
        for button_key, button in self.nav_buttons.items():
            try:
                if button_key == key:
                    button.configure(bg='#18324D', fg='white', highlightbackground=self.ACCENT)
                else:
                    button.configure(bg=self.NAVY, fg='#AEBCCE', highlightbackground=self.BORDER)
            except tk.TclError:
                pass
        self.current_page = key

    def _splitter_set_height(self, height):
        """Set Process Log height while leaving the three top panels flexible."""
        if not hasattr(self, '_splitter_container'):
            return
        try:
            h=self._splitter_container.winfo_height()
            if h <= 0:
                h=520
            # Keep the log compact, but always large enough to read several lines.
            max_log=max(180, h-120)
            height=max(150,min(int(height),max_log))
            self._splitter_container.rowconfigure(0,weight=1,minsize=120)
            self._splitter_container.rowconfigure(2,weight=0,minsize=height)
            self._splitter_log_height=height
        except Exception:
            pass

    def _splitter_drag_start(self,event):
        self._splitter_dragging=True
        self._splitter_drag_origin_y=event.y_root
        self._splitter_start_height=getattr(self,'_splitter_log_height',190)
        self._splitter.configure(bg='#5d6d78')
        self.configure(cursor='sb_v_double_arrow')

    def _splitter_drag_move(self,event):
        if not getattr(self,'_splitter_dragging',False):
            return
        # Drag upward => larger log; downward => smaller log.
        delta=self._splitter_drag_origin_y-event.y_root
        self._splitter_set_height(self._splitter_start_height+delta)

    def _splitter_drag_end(self,event):
        if not getattr(self,'_splitter_dragging',False):
            return
        self._splitter_dragging=False
        self._splitter.configure(bg='#8b9aa5')
        self.configure(cursor='')

