    def _build_logic_table_row(self,table,logic,idx,widths):
        cfg=load_logics().get(logic,DEFAULT_LOGICS[logic])
        row_num=idx+1  # header row 0; logic rows start at 1
        color=self.LOGIC_COLORS[idx]
        vars={'enabled':tk.BooleanVar(value=bool(cfg.get('enabled',True)))}
        _rank_defaults={'minimum_price':1,'entry_time':2,'vwap':3,'orb15':4,'rvol':5,
                        'movement':6,'investment':7,'profit_target':8,'stop_loss':9,'max_trades':10,
                        'open_direction':11,'price_big':12,'price_small':13,'turnover':14,'volume':15}
        _saved_ranks=cfg.get('condition_ranks') if isinstance(cfg.get('condition_ranks'),dict) else _rank_defaults
        self.logic_condition_rank_vars=getattr(self,'logic_condition_rank_vars',{})
        self.logic_condition_rank_vars[logic]={k:tk.StringVar(value=str(_saved_ranks.get(k,d)))
                                                for k,d in _rank_defaults.items()}
        # Hidden strategy fields are kept in the row model so the bottom Optimized
        # Momentum panel can edit the exact same canonical settings used by all modes.
        vars['smart_momentum_pct']=tk.StringVar(value=str(cfg.get('smart_momentum_pct',0.0)))
        vars['smart_momentum_lookback_minutes']=tk.StringVar(value=str(cfg.get('smart_momentum_lookback_minutes',15)))
        vars['smart_rank_limit']=tk.StringVar(value=str(cfg.get('smart_rank_limit',0)))
        vars['smart_rank_by']=tk.StringVar(value=str(cfg.get('smart_rank_by','movement')))
        labels={
            'open_direction':'open_direction','open_movement':'open_movement','minimum_price':'Minimum price (₹)','price_big':'price_big','price_small':'price_small',
            'turnover_cr':'turnover_cr','volume':'volume','buy_amount':'buy_amount','buy_entry_time':'buy_entry_time',
            'buy_exit_time':'Last entry time','profit_target':'profit_target','initial_stop':'initial_stop','activation':'activation',
            'trailing_stop':'trailing_stop','historical_shares':'historical_shares','max_orders':'max_orders',
            'smart_min_score':'smart_min_score','smart_min_volume_ratio':'smart_min_volume_ratio','smart_rank_by':'Rank By (movement or 15m momentum)','smart_rank_limit':'Rank (0 = off; 1 = #1 only)','smart_breakout_lookback':'smart_breakout_lookback',
            'smart_require_market_up':'smart_require_market_up','smart_require_vwap':'smart_require_vwap','smart_require_breakout':'smart_require_breakout',
            'require_52w_high_breakout':'require_52w_high_breakout','require_52w_low_breakdown':'require_52w_low_breakdown',
            'use_price_band':'use_price_band','use_gtt_pretrigger':'use_gtt_pretrigger','require_15m_orb':'require_15m_orb'
        }
        keys=['open_direction','open_movement','minimum_price','price_big','price_small','turnover_cr','volume','buy_amount','buy_entry_time','buy_exit_time',
              'profit_target','initial_stop','activation','trailing_stop','historical_shares','max_orders',
              'smart_min_volume_ratio','smart_require_market_up','smart_require_vwap','smart_require_breakout','require_52w_high_breakout','require_52w_low_breakdown','use_price_band','use_gtt_pretrigger','require_15m_orb']
        name_var=tk.StringVar(value=logic)
        vars['display_name']=name_var
        for col in range(len(widths)):
            table.grid_columnconfigure(col,minsize=widths[col])
        # Logic selector: the checkbox is the master ON/OFF switch for this
        # canonical logic.  Saving the table persists it in logic_settings.json,
        # and Historical/Paper/Live already consume enabled_logics().
        name_cell=tk.Frame(table,bg=color,bd=1,relief='solid')
        name_cell.grid(row=row_num,column=0,sticky='nsew')
        enable_cb=tk.Checkbutton(
            name_cell,text='✓',variable=vars['enabled'],
            bg=color,fg='white',selectcolor='#0b2639',
            activebackground=color,activeforeground='white',
            bd=0,highlightthickness=0,font=('Segoe UI',11,'bold'),
            command=lambda n=logic:self.toggle_logic(n)
        )
        enable_cb.pack(side='left',padx=(6,2),pady=2)
        disp_text = f"★ {logic} [PRIMARY]" if logic == 'Logic 1' else f"{logic} [STANDBY]"
        disp_fg = '#ffe066' if logic == 'Logic 1' else 'white'
        tk.Label(name_cell,text=disp_text,bg=color,fg=disp_fg,font=('Segoe UI',9,'bold'),
                 anchor='center').pack(side='left',fill='both',expand=True,padx=(0,2))
        self._pro_button(name_cell,text='Seq',command=lambda n=logic:self.edit_logic_condition_sequence(n),
                  bg='#17415b',fg='#ffd166',activebackground='#245a78',activeforeground='white',
                  bd=0,font=('Segoe UI',8,'bold'),width=3,padx=1,pady=1).pack(side='right',padx=(1,3))
        # All strategy rows use the same schema and independent GUI variables.

        for col,key in enumerate(keys,1):
            if key.startswith('smart_') and key not in cfg:
                # Logic 1 has no Smart Trend-Momentum fields; keep the exact visual indicator.
                if key in {'smart_require_market_up','smart_require_vwap','smart_require_breakout','require_52w_high_breakout','require_52w_low_breakdown'}:
                    cell=tk.Label(table,text='—',bg='#102f44',fg='#b7c8d5',font=('Segoe UI',9),bd=1,relief='solid')
                else:
                    cell=tk.Label(table,text='—',bg='#102f44',fg='#b7c8d5',font=('Segoe UI',9),bd=1,relief='solid')
                cell.grid(row=row_num,column=col,sticky='nsew')
                continue
            if key in {'smart_mode','smart_require_market_up','smart_require_vwap','smart_require_breakout','require_52w_high_breakout','require_52w_low_breakdown','use_price_band','use_gtt_pretrigger','require_15m_orb'}:
                v=tk.BooleanVar(value=bool(cfg.get(key,False))); vars[key]=v
                cell=tk.Frame(table,bg='#102f44',bd=1,relief='solid')
                cell.grid(row=row_num,column=col,sticky='nsew')
                cb=tk.Checkbutton(cell,variable=v,bg='#102f44',fg='white',selectcolor='#173b58',
                                  activebackground='#102f44',activeforeground='white')
                cb.pack(expand=True)
            elif key=='smart_rank_by':
                v=tk.StringVar(value=str(cfg.get(key,'movement'))); vars[key]=v
                w=ttk.Combobox(table,textvariable=v,values=('movement','momentum_15m'),state='readonly',font=('Segoe UI',8))
                w.grid(row=row_num,column=col,sticky='nsew',padx=2,pady=3)
            elif key=='open_direction':
                v=tk.StringVar(value=str(cfg.get(key,'BOTH'))); vars[key]=v
                w=ttk.Combobox(table,textvariable=v,values=('BOTH','UP','DOWN'),state='readonly',font=('Segoe UI',8))
                w.grid(row=row_num,column=col,sticky='nsew',padx=2,pady=3)
            else:
                default=DEFAULT_LOGICS[logic].get(key,'')
                v=tk.StringVar(value=str(cfg.get(key,default))); vars[key]=v
                w=tk.Entry(table,textvariable=v,bg=self.FIELD,fg='white',insertbackground='white',bd=1,relief='solid',justify='center',font=('Segoe UI',8))
                w.grid(row=row_num,column=col,sticky='nsew',padx=2,pady=3,ipady=4)
        # Keep a visible row-state label in the widget map so other GUI code
        # can inspect the selected state without introducing a second setting.
        self.logic_vars[logic]=vars
        self.logic_frames[logic]=table

    def edit_logic_condition_sequence(self, logic):
        """Edit the condition evaluation order for this Trading Logic only."""
        import tkinter as tk
        from tkinter import messagebox
        names={
            'minimum_price':'Minimum price','entry_time':'Entry time','vwap':'VWAP',
            'orb15':'15-minute ORB','rvol':'RVOL','movement':'Open movement %',
            'investment':'Investment per trade','profit_target':'Profit target',
            'stop_loss':'Stop-loss','max_trades':'Maximum trades per day',
            'open_direction':'Open direction','price_big':'Price big',
            'price_small':'Price small','turnover':'Turnover','volume':'Volume'
        }
        defaults={'minimum_price':1,'entry_time':2,'vwap':3,'orb15':4,'rvol':5,
                  'movement':6,'investment':7,'profit_target':8,'stop_loss':9,
                  'max_trades':10,'open_direction':11,'price_big':12,
                  'price_small':13,'turnover':14,'volume':15}
        ranks=self.logic_condition_rank_vars.setdefault(
            logic,{k:tk.StringVar(value=str(v)) for k,v in defaults.items()})
        win=tk.Toplevel(self)
        win.title(f'{logic} — Condition Sequence')
        win.configure(bg='#0b1728')
        win.transient(self)
        win.grab_set()
        tk.Label(win,text=f'{logic}: condition evaluation order',bg='#0b1728',fg='white',
                 font=('Segoe UI',12,'bold')).pack(anchor='w',padx=12,pady=(12,4))
        tk.Label(win,text='Set unique ranks 1–15. Rank 0 means default order; it does NOT disable a condition.',
                 bg='#0b1728',fg='#b9c9d8',font=('Segoe UI',9)).pack(anchor='w',padx=12,pady=(0,8))
        body=tk.Frame(win,bg='#0b1728'); body.pack(fill='both',expand=True,padx=12,pady=4)
        preview=tk.StringVar(value='')
        def refresh(*_):
            def rv(k):
                try: return int(float(ranks[k].get()))
                except Exception: return 0
            order=sorted(names,key=lambda k:(rv(k)==0,rv(k) if rv(k)>0 else 99,list(names).index(k)))
            preview.set('Trading Logic → '+' → '.join(
                (f'#{rv(k)} ' if rv(k)>0 else 'default ')+names[k] for k in order))
        for row,(key,label) in enumerate(names.items()):
            tk.Label(body,text=label,bg='#102f44',fg='white',anchor='w',width=28,
                     font=('Segoe UI',9)).grid(row=row,column=0,sticky='ew',padx=2,pady=2)
            ent=tk.Entry(body,textvariable=ranks[key],bg='#173b58',fg='#ffd166',
                         insertbackground='white',justify='center',width=7)
            ent.grid(row=row,column=1,padx=4,pady=2)
            ranks[key].trace_add('write',refresh)
        tk.Label(win,textvariable=preview,bg='#102f44',fg='#e5eef5',wraplength=650,
                 justify='left',anchor='w',font=('Segoe UI',8)).pack(fill='x',padx=12,pady=8)
        def save_sequence():
            try:
                vals={k:int(float(ranks[k].get())) for k in names}
                if any(v<0 or v>15 for v in vals.values()):
                    raise ValueError('Every rank must be from 0 to 15.')
                active=[v for v in vals.values() if v>0]
                if len(active)!=len(set(active)):
                    raise ValueError('Non-zero ranks must be unique within this logic.')
                cfg=load_logics()
                cfg[logic]['condition_ranks']=vals
                save_logics(cfg)
                self.status.set(f'{logic} condition sequence saved independently.')
                win.destroy()
            except Exception as exc:
                messagebox.showerror('Invalid condition sequence',str(exc),parent=win)
        buttons=tk.Frame(win,bg='#0b1728'); buttons.pack(fill='x',padx=12,pady=(2,12))
        self._pro_button(buttons,text='Save Sequence',command=save_sequence,bg='#169fe9',
                         fg='white',bd=0,font=('Segoe UI',9,'bold'),pady=6).pack(side='left',fill='x',expand=True,padx=3)
        self._pro_button(buttons,text='Close',command=win.destroy,bg='#173b58',
                         fg='white',bd=0,font=('Segoe UI',9,'bold'),pady=6).pack(side='left',fill='x',expand=True,padx=3)
        refresh()

    def apply_global_range(self):
        """Explicitly apply Price Big/Small range enforcement to all visible rows."""
        value = bool(self.logic_global_range.get())
        for vars in self.logic_vars.values():
            if 'use_price_band' in vars:
                vars['use_price_band'].set(value)
        self.status.set(f'Price Big/Small range {"enabled" if value else "disabled"} for visible logic rows. Press Save to persist.')

    def _sync_global_logic_indicators(self):
        # Compatibility no-op retained for older callers. Global controls must
        # never overwrite row values during Save.
        return

    def delete_logic_row(self, logic=None):
        if logic not in self.logic_vars:
            return
        self.logic_vars[logic]['enabled'].set(False)
        self.toggle_logic(logic)

    def add_logic_row(self):
        self.status.set('All eight strategy slots are already available in the Trading Logic table. Enable a row to use it.')

    def _persist_current_gui_logic_settings(self, show_message=False):
        """Persist exactly what is currently visible in the GUI.

        Each logic row is authoritative for its own entry and Smart Score fields.
        Shared post-buy/pre-arm controls remain shared and are copied to every row.
        The separate Upside Strength Score panel is only a template and is applied
        explicitly with its Apply button; Save never silently overwrites row values.
        """
        cfg=self.collect_all_logics()
        try:
            weak_enabled=bool(self.weak_move_exit_enabled.get())
            weak_high=float(self.weak_move_high_threshold.get())
            weak_stop=float(self.weak_move_stop.get())
        except Exception:
            raise ValueError('Post-Buy Weak-Move Auto Exit values must be numeric.')
        if weak_high < 0 or weak_stop < 0:
            raise ValueError('Post-Buy Weak-Move Auto Exit values cannot be negative.')
        try:
            pre_enabled=bool(self.gtt_pretrigger_enabled.get())
            pre_gap=float(self.gtt_pretrigger_gap.get())
            limit_buffer=float(self.gtt_limit_buffer.get())
        except Exception:
            raise ValueError('BUY Pre-Arm values must be numeric.')
        if pre_gap < 0 or limit_buffer < 0:
            raise ValueError('BUY Pre-Arm values cannot be negative.')
        if pre_gap >= 100:
            raise ValueError('BUY Pre-Arm gap must be less than 100%.')

        # Each Trading Logic owns its own condition_ranks. collect_logic()
        # validates and persists the sequence for that individual row.

        for logic,row in cfg.items():
            row['weak_move_exit_enabled']=weak_enabled
            row['weak_move_high_threshold']=weak_high
            row['weak_move_stop']=weak_stop
            row['use_gtt_pretrigger']=pre_enabled
            row['gtt_pretrigger_gap']=pre_gap
            row['gtt_limit_buffer']=limit_buffer
            # Smart/Upside settings are deliberately NOT copied from the bottom
            # template. They come from this logic's table row.
            row['smart_mode']=bool(row.get('smart_mode', False))
            row['smart_min_score']=int(float(row.get('smart_min_score',9) or 9))
            row['smart_require_vwap']=bool(row.get('smart_require_vwap',True))
            row['smart_require_market_up']=bool(row.get('smart_require_market_up',True))
            row['smart_require_breakout']=bool(row.get('smart_require_breakout',True))
            row['require_15m_orb']=bool(row.get('require_15m_orb',False))
            _rvol_value=row.get('smart_min_volume_ratio',1.5)
            if _rvol_value is None or str(_rvol_value).strip()=='':
                _rvol_value=1.5
            row['smart_min_volume_ratio']=float(_rvol_value)
            row['smart_breakout_lookback']=int(row.get('smart_breakout_lookback',5) or 5)
            row['smart_momentum_pct']=float(row.get('smart_momentum_pct',0.0) or 0.0)
            row['smart_momentum_lookback_minutes']=int(row.get('smart_momentum_lookback_minutes',15) or 15)
            row['smart_rank_limit']=int(float(row.get('smart_rank_limit',0) or 0))
            row['smart_rank_by']=str(row.get('smart_rank_by','movement') or 'movement').strip().lower()
            if row['smart_rank_by'] not in ('movement','momentum_15m'):
                raise ValueError(f'{logic}: Rank By must be movement or momentum_15m.')
            row.pop('smart_rank_top_pct', None)
            row['ma_filter_enabled']=bool(self.ma_filter_enabled.get())
            row['ma_filter_200']=bool(self.ma_filter_200.get())
            row['ma_filter_100']=bool(self.ma_filter_100.get())
            row['ma_filter_20']=bool(self.ma_filter_20.get())
            row['ma_filter_5']=bool(self.ma_filter_5.get())
            row['ma_filter_cross_5']=bool(self.ma_filter_cross_5.get())
            if row['smart_min_score'] < 0 or row['smart_min_score'] > 12:
                raise ValueError(f'{logic}: Smart Score minimum must be between 0 and 12.')
            if row['smart_min_volume_ratio'] < 0 or row['smart_breakout_lookback'] < 0 or row['smart_momentum_pct'] < 0 or row['smart_momentum_lookback_minutes'] <= 0 or row['smart_rank_limit'] < 0 or row['smart_rank_limit'] > 5000:
                raise ValueError(f'{logic}: Smart Momentum settings are invalid.')
        if not any(bool(v.get('enabled',False)) for v in cfg.values()):
            raise ValueError('At least one trading logic must be enabled.')
        saved=save_logics(cfg)
        # Read back from disk so the visible GUI is guaranteed to match the file
        # that Historical/Paper/Live will consume.
        self.load_logic_cards()
        if show_message:
            self.status.set('All trading logic conditions saved.')
            messagebox.showinfo('Logic Saved','All Trading Logic conditions have been saved and will be used by Historical, Paper and Live trading.')
        return saved

    def apply_upside_score_to_all(self):
        """Explicitly copy the bottom Smart Score template into every visible row."""
        try:
            enabled=bool(self.upside_score_enabled.get())
            minimum=int(float(self.upside_score_min.get()))
            vwap=bool(self.upside_score_vwap.get())
            market=bool(self.upside_score_market.get())
            breakout=bool(self.upside_score_breakout.get())
            momentum=float(self.upside_momentum_pct.get())
            rank_top=float(self.upside_rank_top_pct.get())
            vol_ratio=float(self.upside_volume_ratio.get())
            if momentum < 0 or rank_top <= 0 or rank_top > 100 or vol_ratio < 0:
                raise ValueError('Momentum and Relative Volume values are invalid.')
            for logic,vars in self.logic_vars.items():
                if 'smart_mode' in vars: vars['smart_mode'].set(False)
                if 'smart_min_score' in vars: vars['smart_min_score'].set(str(minimum))
                if 'smart_require_vwap' in vars: vars['smart_require_vwap'].set(vwap)
                if 'smart_require_market_up' in vars: vars['smart_require_market_up'].set(market)
                if 'smart_require_breakout' in vars: vars['smart_require_breakout'].set(breakout)
                if 'smart_momentum_pct' in vars: vars['smart_momentum_pct'].set(str(momentum))
                if 'smart_rank_limit' in vars: vars['smart_rank_limit'].set('0')
                if 'smart_min_volume_ratio' in vars: vars['smart_min_volume_ratio'].set(str(vol_ratio))
            self.status.set('Upside Strength Score template applied to all visible logic rows. Press Save to persist.')
        except Exception as e:
            messagebox.showerror('Upside Score Error',str(e))

    def save_all_logic_table(self):
        try:
            self._persist_current_gui_logic_settings(show_message=True)
        except Exception as e:
            messagebox.showerror('Logic Save Error',str(e))

    def reset_all_logic_table(self):
        if not messagebox.askyesno('Reset Trading Logic','Reset all eight logic rows to their defaults? Logic 1 stays enabled; Logic 2–8 stay disabled.'):
            return
        cfg=DEFAULT_LOGICS
        for logic,vals in cfg.items():
            if logic not in self.logic_vars: continue
            for key,default in vals.items():
                if key in self.logic_vars[logic]:
                    self.logic_vars[logic][key].set(default)
            for key,rank_var in self.logic_condition_rank_vars.get(logic,{}).items():
                rank_var.set(str(CONDITION_RANK_DEFAULTS.get(key,0)))
        if hasattr(self,'logic_global_range'):
            self.logic_global_range.set(bool(DEFAULT_LOGICS['Logic 1'].get('use_price_band',False)))
        if hasattr(self,'weak_move_exit_enabled'):
            self.weak_move_exit_enabled.set(bool(DEFAULT_LOGICS['Logic 1'].get('weak_move_exit_enabled',False)))
            self.weak_move_high_threshold.set(str(DEFAULT_LOGICS['Logic 1'].get('weak_move_high_threshold',0.8)))
            self.weak_move_stop.set(str(DEFAULT_LOGICS['Logic 1'].get('weak_move_stop',1.0)))
        if hasattr(self,'gtt_pretrigger_enabled'):
            self.gtt_pretrigger_enabled.set(bool(DEFAULT_LOGICS['Logic 1'].get('use_gtt_pretrigger',True)))
            self.gtt_pretrigger_gap.set(str(DEFAULT_LOGICS['Logic 1'].get('gtt_pretrigger_gap',0.15)))
            self.gtt_limit_buffer.set(str(DEFAULT_LOGICS['Logic 1'].get('gtt_limit_buffer',0.10)))
        if hasattr(self,'upside_score_enabled'):
            self.upside_score_enabled.set(bool(DEFAULT_LOGICS['Logic 1'].get('smart_mode',False)))
            self.upside_score_min.set(str(DEFAULT_LOGICS['Logic 1'].get('smart_min_score',9)))
            self.upside_score_vwap.set(bool(DEFAULT_LOGICS['Logic 1'].get('smart_require_vwap',True)))
            self.upside_score_market.set(bool(DEFAULT_LOGICS['Logic 1'].get('smart_require_market_up',True)))
            self.upside_score_breakout.set(bool(DEFAULT_LOGICS['Logic 1'].get('smart_require_breakout',True)))
        self.save_all_logic_table()

    def copy_logic_table(self):
        try:
            self.copy_logic_card('Logic 1')
            self.load_logic_cards()
            self.status.set('Logic 1 settings copied to all rows; existing enable/disable states were preserved.')
        except Exception as e:
            messagebox.showerror('Copy Error',str(e))

    def build_logic_card(self,parent,logic,idx):
        # Kept as a compatibility wrapper for any internal callers from older builds.
        holder=tk.Frame(parent,bg=self.PANEL2)
        return holder

    def _walk_widgets(self, widget=None):
        widget = self if widget is None else widget
        yield widget
        for child in widget.winfo_children():
            yield from self._walk_widgets(child)

    def _remember_ui_bases(self):
        if self._ui_style_ready:
            return
        for w in self._walk_widgets():
            try:
                f = w.cget('font')
                if f:
                    actual = tkfont.nametofont(f).actual() if isinstance(f, str) and f in tkfont.names() else None
                    if actual:
                        self._ui_base_fonts[w] = dict(actual)
                    elif isinstance(f, tuple):
                        family = f[0] if len(f) else 'Segoe UI'
                        size = int(f[1]) if len(f) > 1 else 9
                        weight = f[2] if len(f) > 2 else 'normal'
                        self._ui_base_fonts[w] = {'family':family,'size':size,'weight':weight}
            except Exception:
                pass
            if isinstance(w, tk.Button):
                try:
                    self._ui_base_button_padding[w] = (int(w.cget('padx')), int(w.cget('pady')))
                except Exception:
                    self._ui_base_button_padding[w] = (7,6)
        self._ui_style_ready=True

    def apply_ui_style(self):
        """GUI-only styling; trading logic, strategy settings and engine files are untouched."""
        try:
            self._remember_ui_bases()
            ui_factor={'Small':0.86,'Normal':1.0,'Large':1.16}.get(self.ui_size.get(),1.0)
            btn_factor={'Small':0.78,'Normal':1.0,'Large':1.35}.get(self.button_size.get(),1.0)
            for w in self._walk_widgets():
                base=self._ui_base_fonts.get(w)
                if base:
                    size=max(7,round(abs(int(base.get('size',9)))*ui_factor))
                    family=base.get('family','Segoe UI')
                    weight=base.get('weight','normal')
                    try:w.configure(font=(family,size,weight))
                    except Exception:pass
                if isinstance(w, tk.Button):
                    basepad=self._ui_base_button_padding.get(w,(7,6))
                    try:
                        bsize=max(7,round((base or {}).get('size',8)*ui_factor*btn_factor))
                        w.configure(font=('Segoe UI',bsize,'bold'),padx=max(6,round(basepad[0]*btn_factor)),pady=max(4,round(basepad[1]*btn_factor)))
                    except Exception:pass
            sizes={'Small':(1120,700),'Normal':(1360,820),'Large':(1540,960)}
            self.geometry(f'{sizes.get(self.ui_size.get(),sizes["Normal"])[0]}x{sizes.get(self.ui_size.get(),sizes["Normal"])[1]}')
            self.status.set(f'GUI size: {self.ui_size.get()} • Button size: {self.button_size.get()}')
            self.update_idletasks()
        except Exception as e:
            self.status.set('GUI style could not be applied: '+str(e))

    def _mousewheel(self,event):
        try:self.canvas.yview_scroll(int(-event.delta/120),'units')
        except Exception:pass

    def load_logic_cards(self):
        cfg=load_logics()
        for logic,vals in cfg.items():
            vars=self.logic_vars.get(logic)
            if not vars:
                continue
            for k,v in vals.items():
                if k in vars: vars[k].set(v)
            _rank_values=vals.get('condition_ranks',{}) if isinstance(vals.get('condition_ranks'),dict) else {}
            for _rank_key,_rank_var in getattr(self,'logic_condition_rank_vars',{}).get(logic,{}).items():
                _rank_var.set(str(_rank_values.get(_rank_key,CONDITION_RANK_DEFAULTS.get(_rank_key,0))))
        if hasattr(self,'logic_global_range'):
            self.logic_global_range.set(bool(cfg.get('Logic 1',{}).get('use_price_band',False)))
        if hasattr(self,'weak_move_exit_enabled'):
            wcfg=cfg.get('Logic 1',{})
            self.weak_move_exit_enabled.set(bool(wcfg.get('weak_move_exit_enabled',False)))
            self.weak_move_high_threshold.set(str(wcfg.get('weak_move_high_threshold',0.8)))
            self.weak_move_stop.set(str(wcfg.get('weak_move_stop',1.0)))
        if hasattr(self,'upside_score_enabled'):
            scfg=cfg.get('Logic 1',{})
            self.upside_score_enabled.set(bool(scfg.get('smart_mode',False)))
            self.upside_score_min.set(str(scfg.get('smart_min_score',9)))
            self.upside_score_vwap.set(bool(scfg.get('smart_require_vwap',True)))
            self.upside_score_market.set(bool(scfg.get('smart_require_market_up',True)))
            self.upside_score_breakout.set(bool(scfg.get('smart_require_breakout',True)))
        if hasattr(self,'gtt_pretrigger_enabled'):
            pcfg=cfg.get('Logic 1',{})
            self.gtt_pretrigger_enabled.set(bool(pcfg.get('use_gtt_pretrigger',True)))
            self.gtt_pretrigger_gap.set(str(pcfg.get('gtt_pretrigger_gap',0.15)))
            self.gtt_limit_buffer.set(str(pcfg.get('gtt_limit_buffer',0.10)))

    def collect_logic(self,logic):
        v=self.logic_vars[logic]
        out={}
        for k,default in DEFAULT_LOGICS[logic].items():
            raw=v[k].get() if k in v else default
            if isinstance(default,bool): out[k]=bool(v[k].get()) if k in v else bool(default)
            elif isinstance(default,int): out[k]=int(float(raw))
            elif isinstance(default,float): out[k]=float(raw)
            else: out[k]=str(raw)
        _rank_vars=getattr(self,'logic_condition_rank_vars',{}).get(logic,{})
        _rank_keys=('minimum_price','entry_time','vwap','orb15','rvol','movement','investment','profit_target','stop_loss','max_trades','open_direction','price_big','price_small','turnover','volume')
        _ranks={}
        for _key in _rank_keys:
            try:
                _raw=float(_rank_vars[_key].get()) if _key in _rank_vars else 0
                if not _raw.is_integer() or not 0 <= int(_raw) <= 15: raise ValueError
                _ranks[_key]=int(_raw)
            except Exception:
                raise ValueError(f'{logic}: rank for {_key} must be an integer from 0 to 15.')
        _active=[v for v in _ranks.values() if v>0]
        if len(_active)!=len(set(_active)):
            raise ValueError(f'{logic}: non-zero condition ranks must be unique within this logic.')
        out['condition_ranks']=_ranks
        if out['open_direction'] not in {'BOTH','UP','DOWN'}: raise ValueError(f'{logic}: Open Direction must be BOTH, UP or DOWN.')
        # Single Source of Truth: ensure trade caps are synchronized so setting 10 gives 10, setting 50 gives 50
        _eff_cap = max(int(out.get('max_orders', 0) or 0), int(out.get('historical_shares', 0) or 0))
        if _eff_cap > 0:
            out['max_orders'] = _eff_cap
            out['historical_shares'] = _eff_cap
        # Zero is valid for numeric settings. Historical Shares=0 means unlimited
        # historical output; a positive value caps unique ranked shares in the
        # historical Excel/replay output. Maximum Orders remains a separate Paper/Live cap.
        numeric=('open_movement','minimum_price','price_small','price_big','turnover_cr','volume','buy_amount','profit_target','initial_stop','activation','trailing_stop','historical_shares','max_orders')
        if any(float(out[k]) < 0 for k in numeric):
            raise ValueError(f'{logic}: numeric values cannot be negative.')
        import datetime as _dt
        for tk in ('buy_entry_time','buy_exit_time'):
            try: _dt.datetime.strptime(str(out[tk]), '%H:%M')
            except Exception: raise ValueError(f'{logic}: {tk} must be HH:MM, e.g. 09:15')
        eh,em=map(int,out['buy_entry_time'].split(':')); xh,xm=map(int,out['buy_exit_time'].split(':'))
        if (xh,xm) <= (eh,em): raise ValueError(f'{logic}: Buy Exit Time must be later than Buy Entry Time.')
        return out

    def toggle_logic(self,logic):
        try:
            cfg=load_logics()
            enabled=bool(self.logic_vars[logic]['enabled'].get())
            cfg[logic]['enabled']=enabled
            save_logics(cfg)
            state='ON' if enabled else 'OFF'
            self.status.set(f'{logic} switched {state}.')
        except Exception as e:
            # Revert the visual switch if persistence failed.
            current=bool(self.logic_vars[logic]['enabled'].get())
            self.logic_vars[logic]['enabled'].set(not current)
            messagebox.showerror('Logic Switch Error',str(e))

    def collect_all_logics(self):
        # Collect every visible row; all eight supported slots are displayed.
        cfg = load_logics()
        for logic in DEFAULT_LOGICS:
            if logic in self.logic_vars:
                cfg[logic] = self.collect_logic(logic)
            else:
                # Keep the last persisted value for hidden/deleted slots.
                cfg[logic] = dict(cfg.get(logic, DEFAULT_LOGICS[logic]))
        return cfg

    def refresh_logic_table(self):
        # Rebuild the complete eight-logic trading panel and keep other GUI state intact.
        outer = getattr(self, 'logic_table_widget', None)
        if outer is None:
            return
        parent = outer.master
        outer.destroy()
        self.build_logic_table(parent)
        self.update_idletasks()
        # Ensure the rebuilt eight-row table is laid out immediately.
        try:
            self.update()
        except Exception:
            pass

    def save_logic_card(self,logic,quiet=False):
        try:
            cfg=load_logics(); cfg[logic]=self.collect_logic(logic); save_logics(cfg); self.status.set(f'{logic} saved.');
            if not quiet: messagebox.showinfo('Logic Saved',f'{logic} settings saved and will be used by Historical, Paper and Live trading.')
        except Exception as e: messagebox.showerror('Logic Save Error',str(e))

    def reset_logic_card(self,logic):
        cfg=DEFAULT_LOGICS[logic]
        for k,v in cfg.items():
            if k in self.logic_vars[logic]: self.logic_vars[logic][k].set(v)
        _defaults={'minimum_price':1,'entry_time':2,'vwap':3,'orb15':4,'rvol':5,
                   'movement':6,'investment':7,'profit_target':8,'stop_loss':9,
                   'max_trades':10,'open_direction':11,'price_big':12,'price_small':13,
                   'turnover':14,'volume':15}
        for k,v in self.logic_condition_rank_vars.get(logic,{}).items():
            v.set(str(cfg.get('condition_ranks',_defaults).get(k,_defaults.get(k,0))))
        self.save_logic_card(logic,quiet=True); self.status.set(f'{logic} reset to defaults.')

    def copy_logic_card(self,logic):
        try:
            src=self.collect_logic(logic)
            if not messagebox.askyesno('Copy Logic',f'Copy all {logic} settings to the other logic card?'): return
            cfg=load_logics()
            for other in DEFAULT_LOGICS:
                if other==logic: continue
                for k,v in src.items():
                    if k in self.logic_vars[other]: self.logic_vars[other][k].set(v)
                for k,v in self.logic_condition_rank_vars.get(other,{}).items():
                    v.set(str((src.get('condition_ranks') or {}).get(k,0)))
                _was_enabled=bool(cfg.get(other,DEFAULT_LOGICS[other]).get('enabled',False))
                _was_enabled=bool(cfg.get(other,DEFAULT_LOGICS[other]).get('enabled',False))
                cfg[other]=dict(src)
                cfg[other]['name']=DEFAULT_LOGICS[other]['name']
                cfg[other]['enabled']=_was_enabled
                cfg[other]['enabled']=_was_enabled
            cfg[logic]=src; save_logics(cfg); self.status.set(f'{logic} copied to the other logic card.')
        except Exception as e: messagebox.showerror('Copy Error',str(e))

    def save_all_logics(self):
        # Compatibility entry point used by older GUI/mobile code. All callers now
        # share the exact same persistence path as the visible Save button.
        return self._persist_current_gui_logic_settings(show_message=False)

    def _start_action_timer(self, reset=True):
        if reset or self._action_started_at is None:
            self._action_started_at=time.monotonic()
        self._action_timer_active=True
        if self._action_timer_id is None:
            self._tick_action_timer()

    def _stop_action_timer(self):
        self._action_timer_active=False
        if self._action_timer_id is not None:
            try: self.after_cancel(self._action_timer_id)
            except Exception: pass
            self._action_timer_id=None

    def _tick_action_timer(self):
        if self._closing or self._action_started_at is None or not self._action_timer_active:
            return
        elapsed=max(0,int(time.monotonic()-self._action_started_at))
        h,rem=divmod(elapsed,3600); m,sec=divmod(rem,60)
        try: self.action_timer_var.set(f'Working time: {h:02d}:{m:02d}:{sec:02d}')
        except Exception: pass
        # Keep this timer on its own Tk after chain. The general UI scheduler is
        # shared with background refreshes and shutdown callbacks; coupling the
        # visible elapsed-time clock to that queue made it harder to diagnose a
        # stalled or cancelled callback chain.
        try:
            self._action_timer_id=self.after(1000, self._tick_action_timer)
        except Exception:
            self._action_timer_id=None

    def _reset_pnl_status(self, mode='IDLE'):
        self._pnl_stats={'mode':mode,'open':0,'completed':0,'wins':0,'losses':0,'gross':0.0,'charges':0.0,'net':0.0,'realized_profit':0.0,'realized_loss':0.0,'last':'No completed trade yet'}
        self._render_pnl_status()

    def _pnl_workbook_candidates(self, mode=''):
        """Return likely result workbooks, newest first.

        Historical replay writes its authoritative Selected Date/YTD result into
        the monthly Trading_Data_YYYY-MM.xlsx workbook, while Paper/Live write
        the same result schema into the main workbook.
        """
        candidates=[]
        mode=str(mode or '').upper()
        if mode.startswith('HISTORICAL'):
            try:
                candidates.extend(MONTHLY_DIR.glob('*/*/Trading_Data_*.xlsx'))
            except Exception:
                pass
        # Paper/Live and fallback historical output use the main workbook.
        if BOOK.exists():
            candidates.append(BOOK)
        unique=[]; seen=set()
        for p in candidates:
            try:
                rp=str(Path(p).resolve())
                if rp in seen or not Path(p).exists():
                    continue
                seen.add(rp); unique.append(Path(p))
            except Exception:
                continue
        return sorted(unique,key=lambda x:x.stat().st_mtime,reverse=True)

    def _refresh_pnl_from_workbook(self, mode=''):
        """Load the persisted trade register into the on-screen P&L Status panel.

        This is intentionally workbook-driven instead of log-driven so Historical,
        Paper and Live all display the same completed/open trade totals and the same
        formula-based P&L values that were actually persisted.
        """
        try:
            mode_u=str(mode or '').upper()
            workbook=None; sheet=None
            for candidate in self._pnl_workbook_candidates(mode_u):
                wb=load_workbook(candidate,read_only=True,data_only=False)
                if mode_u.startswith('HISTORICAL'):
                    preferred=['Selected Date','YTD Historical Data']
                elif mode_u.startswith('PAPER') or mode_u.startswith('LIVE'):
                    # Paper/Live executions are persisted in the dedicated trade ledger.
                    # Reading only YTD/Selected-Date can miss Sell Price/Net P&L and
                    # therefore leave the on-screen win/loss summary at zero.
                    preferred=['Paper Live Trading Shares','YTD Historical Data','Selected Date']
                else:
                    preferred=['YTD Historical Data','Selected Date','Paper Live Trading Shares']
                for name in preferred:
                    if name in wb.sheetnames:
                        ws=wb[name]
                        # Ignore a result workbook that contains no actual rows.
                        if ws.max_row > 1:
                            workbook=candidate; sheet=ws; break
                if workbook is not None:
                    break
                wb.close()
            if workbook is None or sheet is None:
                self.pnl_refresh_var.set('No persisted trade/P&L data yet')
                return False

            header={}
            for c in range(1,sheet.max_column+1):
                h=str(sheet.cell(1,c).value or '').strip()
                if h and h not in header:
                    header[h]=c

            def val(row,name,default=None):
                c=header.get(name)
                return row[c-1] if c and c <= len(row) else default
            def num(v):
                try:
                    if v in (None,''): return 0.0
                    return float(str(v).replace(',','').replace('₹','').strip())
                except Exception:
                    return 0.0
            def dt_key(v):
                if isinstance(v,datetime): return v
                try:
                    return datetime.fromisoformat(str(v).replace('Z',''))
                except Exception:
                    return datetime.min

            rows=[]
            for row in sheet.iter_rows(min_row=2,values_only=True):
                sym=str(val(row,'Symbol','') or '').strip().upper()
                if not sym or sym == 'NO TRADE':
                    continue
                qty=num(val(row,'Qty',val(row,'Buy Qty',0)))
                buy=num(val(row,'Buy Price',0))
                sell_raw=val(row,'Sell Price',None)
                sell_dt_raw=val(row,'Sell Date & Time',None)
                sell_turnover_raw=val(row,'Sell Turnover',None)
                # Historical result sheets store the exit timestamp and sell turnover,
                # rather than a dedicated Sell Price column. Treat a persisted
                # historical exit as completed and derive its average exit price.
                result_marker=str(val(row,'Historical Result','') or '').strip().upper()
                sell_present=(sell_raw not in (None,'') and num(sell_raw)!=0)
                if not sell_present and sell_dt_raw not in (None,''):
                    sell_present=True
                if sell_present and (sell_raw in (None,'') or num(sell_raw)==0):
                    sell_qty_for_price=num(val(row,'Buy Qty',val(row,'Qty',0)))
                    if sell_qty_for_price > 0 and num(sell_turnover_raw) > 0:
                        sell_raw=num(sell_turnover_raw)/sell_qty_for_price
                # The compact YTD/Selected-Date paper/live schema intentionally omits
                # Sell Price.  In that schema the persisted result marker is the
                # authoritative completion state.  Without this fallback the GUI can
                # show fewer completed paper trades than the paper engine actually
                # recorded (especially 15:25 square-offs).
                result_marker=str(val(row,'Historical Result','') or '').strip().upper()
                mode_marker=str(val(row,'Mode','') or '').strip().upper()
                row_status=str(val(row,'Status','') or '').strip().upper()
                row_date=str(val(row,'Date','') or '')[:10]
                today_iso=datetime.now().date().isoformat()
                # The YTD sheet can contain Historical, Paper and Live rows together.
                # The on-screen P&L Summary must show only the requested run type and,
                # for Paper/Live, only today's session.  Without this filter an older
                # historical/current-day row can be counted in the Paper summary.
                if mode_u.startswith('PAPER'):
                    if row_date != today_iso:
                        continue
                    # Dedicated Paper Live ledger identifies the run in Mode; the
                    # historical sheets identify it through Historical Result.
                    if mode_marker and mode_marker != 'PAPER':
                        continue
                    if not mode_marker and not result_marker.startswith('PAPER_'):
                        continue
                elif mode_u.startswith('LIVE'):
                    if row_date != today_iso:
                        continue
                    if mode_marker and mode_marker != 'LIVE':
                        continue
                    if not mode_marker and not result_marker.startswith('LIVE_'):
                        continue
                elif mode_u.startswith('HISTORICAL'):
                    if result_marker.startswith('PAPER_') or result_marker.startswith('LIVE_'):
                        continue
                persisted_completed=(
                    result_marker in {'PAPER_COMPLETED','LIVE_COMPLETED','PAPER_LIVE_COMPLETED'}
                    or (sell_present and row_status in {'CLOSED','COMPLETED','SOLD','SQUARE-OFF','SQUAREOFF','EXITED'})
                    or sell_present
                )
                if qty <= 0 and not sell_present and not persisted_completed:
                    continue
                if persisted_completed:
                    sell_present=True
                gross_raw=val(row,'Gross P&L',None)
                charges_raw=val(row,'Total Charges',None)
                net_raw=val(row,'Net P&L',None)
                gross=num(gross_raw)
                charges=num(charges_raw)
                net=num(net_raw)
                # A row is a completed trade only when a SELL value exists.
                # Historical NO-TRADE summary rows were already excluded above.
                rows.append({
                    'symbol':sym,'qty':qty,'buy':buy,'sell':num(sell_raw),'sell_present':sell_present,
                    'gross':gross,'charges':charges,'net':net,
                    'buy_dt':dt_key(val(row,'Buy Date & Time',None)),
                    'sell_dt':dt_key(val(row,'Sell Date & Time',None)),
                    'exit':str(val(row,'Exit Reason','') or '').strip(),
                    'result_marker':result_marker,
                })

            completed=[r for r in rows if r['sell_present']]
            open_rows=[r for r in rows if not r['sell_present'] and r['qty']>0]
            wins=sum(1 for r in completed if r['net']>0)
            losses=sum(1 for r in completed if r['net']<0)
            gross=sum(r['gross'] for r in completed)
            charges=sum(r['charges'] for r in completed)
            net=sum(r['net'] for r in completed)
            realized_profit=sum(max(r['net'],0.0) for r in completed)
            realized_loss=sum(min(r['net'],0.0) for r in completed)

            if completed:
                last=max(completed,key=lambda r:(r['sell_dt'],r['buy_dt']))
                exit_text=(' — '+last['exit']) if last['exit'] else ''
                last_text=f"SELL {last['symbol']} @ ₹{last['sell']:,.2f}{exit_text}"
            elif open_rows:
                last=max(open_rows,key=lambda r:r['buy_dt'])
                last_text=f"BUY {last['symbol']} qty={int(last['qty']) if last['qty'].is_integer() else last['qty']:g} @ ₹{last['buy']:,.2f}"
            else:
                last_text='No completed trade yet'

            display_mode = ('HISTORICAL' if mode_u.startswith('HISTORICAL') else ('PAPER' if mode_u.startswith('PAPER') else ('LIVE' if mode_u.startswith('LIVE') else mode_u or 'IDLE')))
            self._pnl_stats={'mode':display_mode,'open':len(open_rows),'completed':len(completed),'wins':wins,'losses':losses,'gross':gross,'charges':charges,'net':net,'realized_profit':realized_profit,'realized_loss':realized_loss,'last':last_text}
            self._render_pnl_status()
            self.pnl_refresh_var.set(f"P&L from {workbook.name} / {sheet.title} • refreshed {datetime.now().strftime('%H:%M:%S')}")
            return True
        except Exception as exc:
            self.pnl_refresh_var.set(f'P&L refresh error: {type(exc).__name__}')
            self.logline(f'P&L workbook refresh warning: {exc}')
            return False

    def _render_pnl_status(self):
        st=self._pnl_stats
        for var,val in ((self.pnl_mode_var,st['mode']),(self.pnl_open_var,st['open']),(self.pnl_completed_var,st['completed']),(self.pnl_wins_var,st['wins']),(self.pnl_losses_var,st['losses']),
                        (self.pnl_gross_var,f"₹{st['gross']:,.2f}"),(self.pnl_charges_var,f"₹{st['charges']:,.2f}"),(self.pnl_net_var,f"₹{st['net']:,.2f}"),(self.pnl_last_var,st['last'])):
            try: var.set(val)
            except Exception: pass

    def _update_pnl_from_log(self,text):
        t=str(text)
        st=self._pnl_stats
        upper=t.upper()
        # The paper/live engines reuse the historical downloader and therefore
        # emit many lines containing the word HISTORICAL. Those are data-source
        # messages, not a change of trading mode. Keep the mode selected when the
        # GUI starts the job; only explicit run-type markers may change it.
        if 'PAPER AUTO TRADING' in upper or re.search(r'\bPAPER\s+(?:BUY|SELL)\b',t,re.I):
            st['mode']='PAPER'
        elif 'LIVE TICK AUTO' in upper or re.search(r'\bLIVE\s+(?:BUY|SELL|TRADING)\b',t,re.I):
            st['mode']='LIVE'
        elif st.get('mode') not in {'PAPER','LIVE'} and (
            upper.startswith('STARTING HISTORICAL') or
            upper.startswith('HISTORICAL REPLAY') or
            upper.startswith('HISTORICAL AUTO')
        ):
            st['mode']='HISTORICAL'
        elif st.get('mode') not in {'PAPER','LIVE'} and 'NSE' in upper and 'RUNNING' in upper:
            st['mode']='NSE'
        m=re.search(r'PAPER BUY\b.*?:\s*([A-Za-z0-9&._-]+).*?qty=(\d+).*?price=([0-9.]+).*?at\s*([0-9:.-]+)',t,re.I)
        if m:
            st['open'] += 1
            st['last']=f"BUY {m.group(1).upper()} qty={m.group(2)} @ ₹{float(m.group(3)):,.2f} {m.group(4)}"
        m=re.search(r'PAPER SELL\b.*?:\s*([A-Za-z0-9&._-]+).*?qty=(\d+).*?price=([0-9.]+).*?reason=(.*)$',t,re.I)
        if m:
            st['open']=max(0,st['open']-1); st['completed']+=1
            reason=m.group(4).strip()
            st['last']=f"SELL {m.group(1).upper()} qty={m.group(2)} @ ₹{float(m.group(3)):,.2f} — {reason}"
            # The Action Log can report a completed SELL before the process itself
            # finishes.  Refresh from the persisted Paper/Live ledger immediately so
            # Winning/Losing Trades, Gross/Charges/Net P&L reflect the actual closed
            # trade instead of remaining at zero until PROCESS COMPLETE.
            refresh_mode='LIVE' if re.search(r'LIVE\s+SELL',t,re.I) else 'PAPER'
            # The paper engine persists the SELL before emitting this log line,
            # but Excel/file I/O can finish a little later on slower machines.
            # Refresh immediately and retry briefly so the on-screen Completed /
            # Winning / Losing totals update on the same trade, without changing
            # any entry, exit, charge, or trading logic.
            try:
                self._schedule_ui(lambda rm=refresh_mode: self._refresh_pnl_from_workbook(rm), 50)
                self._schedule_ui(lambda rm=refresh_mode: self._refresh_pnl_from_workbook(rm), 300)
                self._schedule_ui(lambda rm=refresh_mode: self._refresh_pnl_from_workbook(rm), 1000)
            except Exception:
                pass
        # Historical/Paper/Live final reports may be emitted as individual log lines.
        for key,pattern in [('gross',r'Gross P&L:\s*₹?(-?[0-9,]+(?:\.[0-9]+)?)'),('charges',r'Charges:\s*₹?(-?[0-9,]+(?:\.[0-9]+)?)'),('net',r'Net P&L:\s*₹?(-?[0-9,]+(?:\.[0-9]+)?)')]:
            mm=re.search(pattern,t,re.I)
            if mm:
                try: st[key]=float(mm.group(1).replace(',',''))
                except Exception: pass
        mm=re.search(r'Profit Trades:\s*(\d+)',t,re.I)
        if mm: st['wins']=int(mm.group(1))
        mm=re.search(r'Loss Trades:\s*(\d+)',t,re.I)
        if mm: st['losses']=int(mm.group(1))
        if 'No P&L Dashboard data yet' not in t:
            self.pnl_refresh_var.set('P&L status from current Action Log • refreshed '+datetime.now().strftime('%H:%M:%S'))
        self._render_pnl_status()

    def _mobile_process_log_write(self, text):
        """Persist process-log lines into separate mobile Historical vs Live/Paper feeds."""
        try:
            DATA_DIR.mkdir(parents=True, exist_ok=True)
            raw = str(text).rstrip("\n")
            if not raw:
                return
            mode = str(getattr(self, 'pnl_mode_var', tk.StringVar(value='IDLE')).get() or '').upper()
            # Prefer explicit process markers when present; otherwise use the active GUI mode.
            upper = raw.upper()
            if 'HISTORICAL' in upper or 'LIVE SHADOW' in upper:
                target = MOBILE_HIST_LOG
                feed = 'HISTORICAL'
            elif 'PAPER' in upper or 'LIVE' in upper or mode in {'PAPER','LIVE','LIVE TICK AUTO','LIVE SHADOW'}:
                target = MOBILE_TRADE_LOG
                feed = 'LIVE_PAPER'
            else:
                target = MOBILE_HIST_LOG if mode in {'HISTORICAL','NSE'} else MOBILE_TRADE_LOG
                feed = 'HISTORICAL' if target == MOBILE_HIST_LOG else 'LIVE_PAPER'
            row = {'time': datetime.now().isoformat(timespec='seconds'), 'feed': feed, 'message': raw}
            with target.open('a', encoding='utf-8') as fh:
                fh.write(json.dumps(row, ensure_ascii=False) + '\n')
            # Avoid reading the entire mobile log on every line. This previously
            # caused repeated full-file disk reads during large historical replays.
            try:
                if target.stat().st_size > 2_000_000:
                    lines = target.read_text(encoding='utf-8').splitlines()
                    if len(lines) > 5000:
                        tmp = target.with_suffix(target.suffix + '.tmp')
                        tmp.write_text('\\n'.join(lines[-5000:]) + '\\n', encoding='utf-8')
                        tmp.replace(target)
            except Exception:
                pass
        except Exception:
                pass
        except Exception:
            pass

    def logline(self,s):
        """Thread-safe process-log entry point.

        Worker threads must never touch Tk widgets/variables directly.  The
        previous implementation parsed P&L and modified Tk StringVars before
        scheduling the actual text insert, which could silently break the log
        stream when Historical/Paper/Shadow was running from a background
        thread.  Everything UI-related now happens inside the Tk event loop.
        """
        text=str(s)
        def _write():
            try:
                # Persist the mobile feed FIRST. Mobile logging must not depend
                # on a particular Tk widget being visible.
                self._mobile_process_log_write(text)
                log_widget = getattr(self, 'smart_log', None)
                if log_widget is None:
                    return
                # The working timer belongs only to the currently running action.
                if text.strip() and self._action_timer_active:
                    self._start_action_timer(reset=False)
                self._update_pnl_from_log(text)
                m=re.search(r'\b(?:PAPER|LIVE) BUY(?:\s+\w+)?(?:\s+#\d+/[^:]+)?:\s*([A-Za-z0-9&._-]+)',text,re.I)
                if m:
                    self.open_buy_symbols.add(m.group(1).upper())
                if re.search(r'\b(?:PAPER SELL|LIVE .*SELL|LIVE .*EXIT|FILLED .*SELL)',text,re.I):
                    for sym in list(self.open_buy_symbols):
                        if re.search(rf'\b{re.escape(sym)}\b',text,re.I):
                            self.open_buy_symbols.discard(sym)
                # `log_widget` is already the visible Process Log (`smart_log`).
                # Do not insert the same line a second time; the previous code
                # duplicated every child-process message in the UI.
                log_widget.configure(state='normal')
                log_widget.insert('end',text+'\n')
                # Keep the visible log bounded to prevent Tk scrolling/rendering
                # from slowing down during long historical or paper sessions.
                try:
                    if int(log_widget.index('end-1c').split('.')[0]) > 4000:
                        log_widget.delete('1.0', '1001.0')
                except Exception:
                    pass
                log_widget.see('end')
                log_widget.configure(state='disabled')
                if hasattr(self,'smart_mode_var'):
                    self.smart_mode_var.set(str(self.pnl_mode_var.get()).upper())
            except Exception as exc:
                # Never allow a cosmetic log/P&L parsing error to kill the
                # process-reader thread.  Put the diagnostic directly into the
                # same UI queue for visibility.
                try:
                    log_widget = getattr(self, 'smart_log', None)
                    if log_widget is not None:
                        log_widget.configure(state='normal')
                        log_widget.insert('end',f'[GUI LOG ERROR] {type(exc).__name__}: {exc}\n')
                        log_widget.see('end')
                        log_widget.configure(state='disabled')
                except Exception:
                    pass
        self._schedule_ui(_write, 0)
