    def start_market_strip(self):
        if getattr(self, '_market_thread_started', False):
            return
        self._market_thread_started=True
        threading.Thread(target=self._market_refresh_loop, daemon=True, name='market-refresh').start()

    @staticmethod
    def _quote_value(row, *keys):
        for key in keys:
            value=row.get(key) if isinstance(row,dict) else None
            if value not in (None,''):
                try: return float(str(value).replace(',',''))
                except Exception: return value
        return None

    def _format_index(self, label, row):
        if not row:
            return f'{label}: --'
        ltp=self._quote_value(row,'ltp','last_price','close','LTP')
        pct=self._quote_value(row,'ltp_percent_change','percentage_change','percent_change','change_percent','change_percentage')
        if pct is None:
            prev=self._quote_value(row,'previous_close','prev_close','previousClose')
            if ltp is not None and prev not in (None,0): pct=(ltp-prev)/prev*100
        if ltp is None:
            return f'{label}: --'
        try:
            arrow='▲' if float(pct or 0)>0 else ('▼' if float(pct or 0)<0 else '—')
            return f'{label}: {ltp:,.2f} {arrow} {float(pct or 0):+.2f}%'
        except Exception:
            return f'{label}: {ltp}'

    def _market_breeze(self):
        from breeze_connect import BreezeConnect
        key=self.api_key.get().strip(); secret=self.api_secret.get().strip(); token=self.session_token.get().strip()
        if not (key and secret and token):
            raise RuntimeError('Breeze credentials not saved')
        stamp=key+'|'+token
        if self._market_breeze_conn is not None and self._market_session_stamp == stamp:
            return self._market_breeze_conn
        breeze=BreezeConnect(api_key=key)
        breeze.generate_session(api_secret=secret,session_token=token)
        self._market_breeze_conn=breeze
        self._market_session_stamp=stamp
        return breeze

    def _get_quote_row(self,breeze,stock_code,exchange_code, fresh=False):
        # Breeze's documented limit is 100 calls/minute and 5,000/day. The Home
        # Scanner and Smart Trade share this cache to avoid duplicate quote calls.
        # Live order revalidation explicitly passes fresh=True to bypass the cache.
        cache_key=(str(exchange_code).upper(),str(stock_code).upper())
        self._market_last_error=''
        now_mono=time.monotonic()
        if not fresh:
            with _QUOTE_CACHE_LOCK:
                cached=_QUOTE_CACHE.get(cache_key)
                if cached:
                    ttl=_QUOTE_CACHE_TTL_SECONDS if cached[1] is not None else cached[2]
                    if now_mono-cached[0] < ttl:
                        if cached[1] is None and len(cached)>3:
                            self._market_last_error=str(cached[3])
                        return dict(cached[1]) if cached[1] is not None else None
        # Breeze equity/index quotes use product_type=cash. The API can return a
        # second placeholder row (exchange_code=NA, ltp=0), so select the first
        # real quote rather than blindly taking rows[0].
        candidates=[stock_code]
        if stock_code == 'INDIAVIX':
            candidates=['INDIAVIX','INDVIX']
        last_error=None
        for code in candidates:
            try:
                # Retry one transient read failure (503/timeout/empty non-JSON response).
                # Do not retry stable unsupported-symbol errors or any order endpoint.
                r=None
                for quote_attempt in range(2):
                    try:
                        r=breeze.get_quotes(
                            stock_code=code, exchange_code=exchange_code, product_type='cash',
                            expiry_date='', right='', strike_price=''
                        )
                        status=str(r.get('Status','')) if isinstance(r,dict) else ''
                        err_text=str(r.get('Error') or '').lower() if isinstance(r,dict) else ''
                        transient_status=status in {'502','503','504'}
                        transient_error=any(x in err_text for x in ('service unavailable','temporarily unavailable','timeout'))
                        if quote_attempt == 0 and (transient_status or transient_error):
                            time.sleep(0.6)
                            continue
                        break
                    except Exception as e:
                        last_error=str(e)
                        low=str(e).lower()
                        transient=any(x in low for x in ('503','502','504','timeout','timed out','expecting value','jsondecode','remote end closed','connection reset','connection aborted'))
                        if quote_attempt == 0 and transient:
                            time.sleep(0.6)
                            continue
                        raise
                rows=r.get('Success') if isinstance(r,dict) else None
                if isinstance(rows,list):
                    valid=[]
                    for row in rows:
                        if not isinstance(row,dict):
                            continue
                        try:
                            ltp=float(str(row.get('ltp','0')).replace(',',''))
                        except Exception:
                            ltp=0.0
                        if ltp>0 and str(row.get('exchange_code','')).upper()==str(exchange_code).upper():
                            valid.append(row)
                    if valid:
                        selected=dict(valid[0])
                        with _QUOTE_CACHE_LOCK:
                            _QUOTE_CACHE[cache_key]=(time.monotonic(),selected,_QUOTE_CACHE_TTL_SECONDS,'')
                            # Bound memory if users scan many symbols/exchanges.
                            if len(_QUOTE_CACHE)>500:
                                oldest=sorted(_QUOTE_CACHE.items(),key=lambda kv:kv[1][0])[:100]
                                for old_key,_ in oldest: _QUOTE_CACHE.pop(old_key,None)
                        return dict(selected)
                if isinstance(r,dict) and (r.get('Error') or str(r.get('Status','200')) != '200'):
                    last_error=str(r.get('Error') or f"Breeze quote endpoint returned Status={r.get('Status')!r}")
            except Exception as e:
                last_error=str(e)
        if last_error:
            self._market_last_error=f'{stock_code}: {last_error}'
            # Unsupported symbols are stable failures and should not be queried on
            # every scan. Transient 503/network errors get only a short negative cache.
            err_lower=last_error.lower()
            negative_ttl=300.0 if ('stock may not be available' in err_lower or 'check stock code' in err_lower) else 15.0
            if not fresh:
                with _QUOTE_CACHE_LOCK:
                    _QUOTE_CACHE[cache_key]=(time.monotonic(),None,negative_ttl,self._market_last_error)
        return None

    def _get_broker_positions(self,breeze):
        names=[]
        try:
            r=breeze.get_portfolio_positions()
            rows=r.get('Success') if isinstance(r,dict) else None
            if isinstance(rows,list):
                for x in rows:
                    if not isinstance(x,dict): continue
                    qty=self._quote_value(x,'net_quantity','net_qty','quantity','open_quantity')
                    if qty is not None and qty>0:
                        sym=str(x.get('stock_code') or x.get('symbol') or x.get('short_name') or '').strip()
                        if sym: names.append(sym.upper())
        except Exception:
            pass
        return names

    def _schedule_icici_portfolio_refresh(self):
        if self._closing:
            return
        if all(v.get().strip() for v in (self.api_key, self.api_secret, self.session_token)):
            self.refresh_icici_portfolio()
        self._schedule_ui(self._schedule_icici_portfolio_refresh, 300000)

    def refresh_icici_portfolio(self):
        """Fetch ICICI Direct holdings through the authenticated Breeze API in a worker thread."""
        if not hasattr(self, 'icici_portfolio_status'):
            return
        self.icici_portfolio_status.set('Loading holdings…')
        threading.Thread(target=self._icici_portfolio_worker, daemon=True, name='icici-portfolio-refresh').start()

    def _icici_portfolio_worker(self):
        """Read holdings, enrich with best-available quotes, and render portfolio totals."""
        try:
            breeze = self._market_breeze()
            rows = []
            errors = []
            # Try the dedicated demat holdings endpoint first, then the exchange portfolio API.
            for method_name in ('get_demat_holdings', 'get_portfolio_holdings'):
                method = getattr(breeze, method_name, None)
                if not callable(method):
                    continue
                try:
                    response = method()
                    got = response.get('Success') if isinstance(response, dict) else None
                    if isinstance(got, list) and got:
                        rows = got
                        break
                    if isinstance(response, dict) and (response.get('Error') or response.get('error')):
                        errors.append(str(response.get('Error') or response.get('error')))
                except Exception as exc:
                    errors.append(f'{method_name}: {exc}')
            if not rows:
                raise RuntimeError(('; '.join(errors) or 'No holdings returned by demat/portfolio endpoints')[:240])
            display = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                symbol = str(row.get('stock_code') or row.get('stockCode') or row.get('symbol') or row.get('short_name') or row.get('company_name') or row.get('scrip_name') or '').strip()
                if not symbol:
                    continue
                def num(*keys):
                    for key in keys:
                        value = row.get(key)
                        if value in (None, ''): continue
                        try: return float(str(value).replace(',', '').replace('₹','').strip())
                        except (TypeError, ValueError): pass
                    return None
                qty = num('quantity','total_quantity','holding_quantity','available_quantity','net_quantity','demat_qty','free_quantity')
                avg = num('average_price','avg_price','average_cost','cost_price','purchase_price','average_buy_price','buy_avg_price')
                ltp = num('ltp','market_price','closing_price','last_price','last_traded_price')
                value = num('market_value','current_value','holding_value','marketValue','current_market_value')
                # When no usable LTP is included in holdings response, ask Breeze for a fresh quote.
                if (ltp is None or ltp <= 0) and symbol:
                    exchange = str(row.get('exchange_code') or row.get('exchange') or 'NSE').upper()
                    quote = self._get_quote_row(breeze, symbol, exchange)
                    if quote:
                        ltp = self._quote_value(quote, 'ltp','last_price','LTP')
                investment = num('investment_value','cost_value','total_cost','buy_value')
                if investment is None and qty is not None and avg is not None: investment = qty * avg
                if value is None and qty is not None and ltp is not None and ltp > 0: value = qty * ltp
                pnl = num('unrealized_profit_loss','unrealized_pnl','pnl','profit_loss')
                if pnl is None and value is not None and investment is not None: pnl = value - investment
                pct = (pnl / investment * 100.0) if pnl is not None and investment not in (None, 0) else None
                display.append({'symbol':symbol,'qty':qty,'avg':avg,'ltp':ltp,'investment':investment,'value':value,'pnl':pnl,'pct':pct})
            if not display:
                raise RuntimeError('The API returned holdings, but no usable holding symbols were found')
            self._schedule_ui(lambda data=display: self._render_icici_portfolio(data), 0)
        except Exception as exc:
            msg = str(exc)[:240]
            self._schedule_ui(lambda error=msg: self.icici_portfolio_status.set('Portfolio unavailable: ' + error), 0)

    def _render_icici_portfolio(self, rows):
        if not hasattr(self, 'icici_portfolio_tree'):
            return
        for item in self.icici_portfolio_tree.get_children(''):
            self.icici_portfolio_tree.delete(item)
        def fmt(v):
            return '—' if v is None else f'{v:,.2f}'
        totals = {'investment':0.0,'current':0.0,'pnl':0.0}
        have_investment = have_current = have_pnl = False
        for r in rows:
            qty,avg,ltp,investment,value,pnl,pct=(r.get(k) for k in ('qty','avg','ltp','investment','value','pnl','pct'))
            if investment is not None: totals['investment'] += investment; have_investment=True
            if value is not None: totals['current'] += value; have_current=True
            if pnl is not None: totals['pnl'] += pnl; have_pnl=True
            self.icici_portfolio_tree.insert('', 'end', values=(r['symbol'],fmt(qty),fmt(avg),fmt(ltp),fmt(investment),fmt(value),fmt(pnl),('—' if pct is None else f'{pct:+.2f}%')))
        totals_pct = totals['pnl']/totals['investment']*100 if have_pnl and have_investment and totals['investment'] else None
        values = {'investment':fmt(totals['investment']) if have_investment else '—','current':fmt(totals['current']) if have_current else '—','pnl':fmt(totals['pnl']) if have_pnl else '—','pct':('—' if totals_pct is None else f'{totals_pct:+.2f}%')}
        for key,value in values.items():
            var,accent,value_label=self.icici_portfolio_metrics[key]
            var.set(('₹ ' if key!='pct' else '')+value if key!='pct' else value)
            if key in ('pnl','pct') and ((totals.get('pnl',0)<0) if key=='pnl' else (totals_pct is not None and totals_pct<0)):
                # Use red for losses, green for gains.
                card_fg='#FB7185'
            elif key in ('pnl','pct'):
                card_fg='#22C55E'
            else:
                card_fg=accent
            # Keep label variables simple; value label is identified by stored widget variable below.
            value_label.configure(fg=card_fg)
        self.icici_portfolio_status.set(f'Updated {datetime.now().strftime("%H:%M:%S")} • {len(rows)} holding(s) • read-only')

    def _market_refresh_loop(self):
        # One authenticated Breeze session is reused. Refreshing it every few seconds
        # can cause intermittent quote failures and wastes API calls. Polling once per
        # minute keeps the strip automatic while staying comfortably within Breeze
        # rate limits.
        while not self.market_stop.is_set():
            try:
                breeze=self._market_breeze()
                nse=self._get_quote_row(breeze,'NIFTY','NSE')
                bse=self._get_quote_row(breeze,'SENSEX','BSE')
                vix=self._get_quote_row(breeze,'INDIAVIX','NSE')
                broker_buys=self._get_broker_positions(breeze)
                combined=sorted(set(self.open_buy_symbols).union(broker_buys))
                buys='BUY SHARES: '+(', '.join(combined) if combined else '—')
                self._schedule_ui(lambda n=nse,b=bse,v=vix,buys=buys: self._set_market_strip(n,b,v,buys), 0)
                # If the session has expired, force a fresh login on the next cycle.
                if nse is None and bse is None and vix is None:
                    self._market_breeze_conn=None
                    self._market_session_stamp=''
            except Exception as e:
                self._market_last_error=str(e)
                self._market_breeze_conn=None
                self._market_session_stamp=''
                buys='BUY SHARES: '+(', '.join(sorted(self.open_buy_symbols)) if self.open_buy_symbols else '—')
                self._schedule_ui(lambda buys=buys:self._set_market_strip(None,None,None,buys), 0)
            self.market_stop.wait(60)

    def _set_market_strip(self,nse,bse,vix,buys):
        if not self.market_labels: return
        self.market_labels['buys'].set(buys)
        self.market_labels['nse'].set(self._format_index('NSE',nse))
        self.market_labels['bse'].set(self._format_index('BSE',bse))
        self.market_labels['vix'].set(self._format_index('INDIA VIX',vix))

