    def _scanner_logic_conditions(self):
        """Read the strongest enabled logic as the scanner's buy gate."""
        candidates=[]
        for logic, vars in getattr(self,'logic_vars',{}).items():
            try:
                if not bool(vars['enabled'].get()): continue
                def num(k, default=0.0):
                    try: return float(vars[k].get())
                    except Exception: return default
                candidates.append({
                    'name':logic,
                    'movement':num('open_movement',0.0),
                    'turnover':num('turnover_cr',0.0),
                    'volume':num('volume',0.0),
                    'direction':str(vars.get('open_direction',tk.StringVar(value='BOTH')).get()).upper(),
                    'entry':str(vars.get('buy_entry_time',tk.StringVar(value='09:15')).get()),
                    'exit':str(vars.get('buy_exit_time',tk.StringVar(value='15:20')).get()),
                })
            except Exception:
                continue
        if not candidates:
            return {'name':'Scanner Default','movement':3.0,'turnover':1.0,'volume':50000.0,'direction':'UP','entry':'09:15','exit':'15:20'}
        # Prefer the strictest movement/volume gate so the queue does not become noisy.
        return max(candidates,key=lambda x:(x['movement'],x['volume'],x['turnover']))

    def _scanner_quote_metrics(self,row):
        if not isinstance(row,dict): return None
        ltp=self._quote_value(row,'ltp','last_price','close','LTP')
        prev=self._quote_value(row,'previous_close','prev_close','previousClose')
        pct=self._quote_value(row,'ltp_percent_change','percentage_change','percent_change','change_percent','change_percentage')
        if pct is None and ltp is not None and prev not in (None,0): pct=(ltp-prev)/prev*100
        vol=self._quote_value(row,'total_quantity_traded','total_quantity','volume','quantity_traded','volume_traded') or 0
        turnover=self._quote_value(row,'total_turnover','turnover','turnover_value') or 0
        # Breeze values may arrive in rupees while the UI wants crore.
        try:
            if turnover > 1000000: turnover_cr=turnover/10000000.0
            else: turnover_cr=turnover
        except Exception: turnover_cr=0.0
        if ltp is None: return None
        return {'ltp':float(ltp),'prev':float(prev or 0),'pct':float(pct or 0),'volume':float(vol or 0),'turnover':float(turnover_cr or 0)}

