    def _update_fcfs(self,gainers,logic,now):
        try:
            tm=now.time(); entry=datetime.strptime(logic['entry'],'%H:%M').time(); exit_t=datetime.strptime(logic['exit'],'%H:%M').time()
            in_window=entry <= tm <= exit_t
        except Exception: in_window=True
        for row in gainers:
            movement_ok=row['pct'] >= logic['movement']
            turnover_ok=row['turnover'] >= logic['turnover'] if logic['turnover']>0 else True
            volume_ok=row['volume'] >= logic['volume'] if logic['volume']>0 else True
            direction_ok=(logic['direction'] in ('UP','BOTH') and row['pct']>0) or logic['direction']=='BOTH'
            qualified=movement_ok and turnover_ok and volume_ok and direction_ok and in_window
            sym=row['symbol']
            if qualified and sym not in self.fcfs_queue:
                reasons=[]
                reasons.append(f"Move {row['pct']:+.2f}% ≥ {logic['movement']:.2f}%")
                if logic['volume']>0: reasons.append(f"Vol {int(row['volume']):,} ≥ {int(logic['volume']):,}")
                if logic['turnover']>0: reasons.append(f"Turnover {row['turnover']:.2f}Cr ≥ {logic['turnover']:.2f}Cr")
                self.fcfs_queue[sym]={'first_seen':now,'row':dict(row),'trigger':' • '.join(reasons),'status':'READY — PAPER / MANUAL BUY'}
            elif sym in self.fcfs_queue:
                self.fcfs_queue[sym]['row']=dict(row)
        # Keep only recent/active candidates; do not let the queue grow forever.
        cutoff=now-timedelta(hours=6)
        self.fcfs_queue={s:v for s,v in self.fcfs_queue.items() if v['first_seen']>=cutoff}

    def _render_scanner(self,gainers,losers,activity):
        self._fill_scanner_frame(self.gainers_frame,gainers,'gain')
        self._fill_scanner_frame(self.losers_frame,losers,'loss')
        self._fill_scanner_frame(self.activity_frame,activity,'activity')
        for item in self.fcfs_tree.get_children(): self.fcfs_tree.delete(item)
        ordered=sorted(self.fcfs_queue.items(),key=lambda kv:kv[1]['first_seen'])[:12]
        for pos,(sym,item) in enumerate(ordered,1):
            r=item['row']; t=item['first_seen'].strftime('%H:%M:%S')
            self.fcfs_tree.insert('', 'end', values=(pos,t,sym,f"{r['pct']:+.2f}%",f"{int(r['volume']):,}",f"{r['turnover']:.2f}",item['trigger'],item['status']))

    def _fill_scanner_frame(self,frame,rows,kind):
        for child in frame.winfo_children(): child.destroy()
        hdr=tk.Frame(frame,bg='#0D1929'); hdr.pack(fill='x',padx=5,pady=(4,1))
        for text,w in [('SYMBOL',9),('LTP',10),('%',8),('VOL',12)]: tk.Label(hdr,text=text,bg='#0D1929',fg='#5F7890',font=('Segoe UI',7,'bold'),width=w,anchor='e' if text!='SYMBOL' else 'w').pack(side='left',padx=2)
        for idx,r in enumerate(rows[:20],1):
            bg='#101D2F' if idx%2 else '#0D1929'
            row=tk.Frame(frame,bg=bg); row.pack(fill='x',padx=5)
            pct=r['pct']; fg='#68E0A3' if pct>0 else ('#FF7C88' if pct<0 else '#C8D4E1')
            tk.Label(row,text=f'{idx:02d}  {r["symbol"]}',bg=bg,fg='#E8EEF7',font=('Consolas',7,'bold'),width=9,anchor='w').pack(side='left',padx=2,pady=2)
            tk.Label(row,text=f'{r["ltp"]:,.2f}',bg=bg,fg='#D8E4EF',font=('Consolas',7),width=10,anchor='e').pack(side='left',padx=2)
            tk.Label(row,text=f'{pct:+.2f}%',bg=bg,fg=fg,font=('Consolas',7,'bold'),width=8,anchor='e').pack(side='left',padx=2)
            vol=f'{int(r["volume"]):,}' if r['volume'] else '—'
            tk.Label(row,text=vol,bg=bg,fg='#8FA3B8',font=('Consolas',7),width=12,anchor='e').pack(side='left',padx=2)

