    def _smart_trade_logic_config(self):
        logs=load_logics()
        enabled=[]
        for name,cfg in logs.items():
            if isinstance(cfg,dict) and bool(cfg.get('enabled',False)): enabled.append((name,cfg))
        if not enabled:
            name='Logic 1'; cfg=dict(DEFAULT_LOGICS.get(name,{}))
        else:
            name,cfg=max(enabled,key=lambda kv:(float(kv[1].get('open_movement',0) or 0),float(kv[1].get('volume',0) or 0),float(kv[1].get('turnover_cr',0) or 0)))
        return name,cfg

    def _score_smart_trade(self,r,nm,cfg,logic_name):
        px=float(r.get('ltp') or 0); op=float(r.get('open') or px); hi=float(r.get('high') or px); lo=float(r.get('low') or px); pct=float(r.get('pct') or 0)
        # Use India market time explicitly instead of the computer's local timezone.
        now=self._smart_ist_now().time()
        if not (datetime.strptime('09:20','%H:%M').time() <= now <= datetime.strptime('15:10','%H:%M').time()): return None
        if px<=0 or op<=0: return None
        day_range=max(hi-lo,px*0.001)
        range_pos=max(0,min(1,(px-lo)/day_range))
        if pct<=0: return None
        # Cross-sectional quality score: momentum + breakout location + liquidity + market alignment,
        # with penalties for excessive extension and poor risk/reward.
        momentum=min(30,max(0,pct*5.5))
        breakout=min(22,max(0,(range_pos-0.55)*48))
        activity=min(18,max(0,7 + (1 if r.get('volume',0)>0 else 0) + (3 if r.get('turnover',0)>=max(5,float(cfg.get('turnover_cr',0) or 0)) else 0)))
        market=min(12,max(0,float(nm.get('pct',0))*3 if nm.get('pct',0)>0 else 0))
        extension_penalty=max(0,(pct-4.5)*4.0)
        # Prefer a strategy-defined stop/target; this keeps the idea aligned with the existing engine.
        stop=initial_stop(px,cfg) if float(cfg.get('initial_stop',0) or 0)>0 else px*0.992
        target=target_price(px,cfg) if float(cfg.get('profit_target',0) or 0)>0 else px*1.015
        risk=max(px-stop,px*0.0025); reward=max(target-px,0); rr=reward/risk if risk>0 else 0
        rr_bonus=min(14,max(0,(rr-1.0)*8))
        score=max(0,min(100,round(momentum+breakout+activity+market+rr_bonus-extension_penalty)))
        threshold=int(self.smart_trade_score_threshold.get())
        if score<threshold: return None
        # Respect the canonical entry gate as a prerequisite for a live BUY suggestion.
        entry=entry_check_local(px,op,float(r.get('prev') or 0),float(r.get('volume') or 0),float(r.get('turnover') or 0),cfg)
        if not entry.get('passed'): return None
        setup=[]
        setup.append(f'Momentum {pct:+.2f}%')
        setup.append(f'Day-range position {range_pos*100:.0f}%')
        setup.append(f'NIFTY {float(nm.get("pct",0)):+.2f}%')
        setup.append(f'R:R {rr:.2f}')
        qty=0
        try:
            risk_budget=max(1,float(self.smart_trade_risk.get()))
            qty=int(risk_budget//risk) if risk>0 else 0
            max_value=max(1,float(self.smart_trade_max_value.get()))
            qty=min(qty,int(max_value//px))
            if qty<=0: return None
        except Exception: return None
        return {'symbol':r['symbol'],'score':score,'entry':px,'stop':stop,'target':target,'rr':rr,'pct':pct,'volume':r.get('volume',0),'turnover':r.get('turnover',0),'setup':' • '.join(setup),'logic':logic_name,'cfg':dict(cfg),'qty':qty,'first_seen':datetime.now(),'range_pos':range_pos}

    def _render_smart_trade(self,ideas):
        for item in self.smart_trade_tree.get_children(): self.smart_trade_tree.delete(item)
        idea_map={x['symbol']:x for x in ideas}
        market_rows=list(getattr(self,'smart_trade_market_rows',[]) or [])
        # Always show the Top-30 liquid universe.  BUY IDEA rows are populated
        # with the full strategy details; non-qualifying rows remain visible as
        # WAIT/filtered candidates with their live quote metrics.
        source = market_rows[:30] if market_rows else list(ideas[:30])
        for i,r in enumerate(source,1):
            sym=str(r.get('symbol',''))
            x=idea_map.get(sym)
            if x:
                vals=(i,sym,x['score'],f"₹{x['entry']:,.2f}",f"₹{x['stop']:,.2f}",f"₹{x['target']:,.2f}",f"{x['rr']:.2f}",f"{x['pct']:+.2f}%",f"{x['turnover']:.1f}Cr",x['setup'],'BUY IDEA')
            else:
                px=float(r.get('ltp') or 0); pct=float(r.get('pct') or 0); turn=float(r.get('turnover') or 0)
                vals=(i,sym,'—',f"₹{px:,.2f}" if px else '—','—','—','—',f"{pct:+.2f}%",f"{turn:.1f}Cr",'Does not meet current BUY conditions','WAIT / FILTERED')
            self.smart_trade_tree.insert('', 'end', iid=f"smart_{i}_{sym}", values=vals)
        if ideas:
            self.smart_trade_tree.selection_set(f"smart_{next((i for i,r in enumerate(source,1) if r.get('symbol')==ideas[0]['symbol']),1)}_{ideas[0]['symbol']}")
            self.smart_trade_select()
        elif source:
            self.smart_detail_var.set('Top-30 liquid shares are loaded. No share currently passes the complete BUY conditions/score threshold. WAIT is a valid trading decision.')
            self.smart_action_var.set('WAIT — NO QUALIFYING BUY')
        else:
            self.smart_detail_var.set('Waiting for live NSE quotes to populate the Top-30 Smart Trading universe.')
            self.smart_action_var.set('WAITING FOR LIVE DATA')

    def smart_trade_select(self,event=None):
        sel=self.smart_trade_tree.selection()
        if not sel: return
        iid=sel[0]
        sym=iid.split('_',2)[-1] if iid.startswith('smart_') else iid
        idea=next((x for x in self.smart_trade_rows if x['symbol']==sym),None)
        if not idea: return
        self.smart_trade_selected=idea
        self.smart_detail_var.set(f"{sym} • Score {idea['score']}/100 • Entry ₹{idea['entry']:,.2f} • Stop ₹{idea['stop']:,.2f} • Target ₹{idea['target']:,.2f} • R:R {idea['rr']:.2f}\n{idea['setup']} • Canonical logic: {idea['logic']}")
        self.smart_risk_var.set(f"Risk / share: ₹{max(0,idea['entry']-idea['stop']):,.2f}")
        self.smart_qty_var.set(f"Suggested qty: {idea['qty']} • Max value ₹{idea['qty']*idea['entry']:,.0f}")
        self.smart_action_var.set('READY — click BUY NOW')

