    def _smart_validation_gate(self):
        d=self._load_smart_validation(); trades=d.get('trades',[]) if isinstance(d,dict) else []
        closed=[t for t in trades if t.get('status')=='CLOSED']
        wins=[t for t in closed if float(t.get('pnl',0) or 0)>0]
        losses=[t for t in closed if float(t.get('pnl',0) or 0)<0]
        gross_win=sum(float(t.get('pnl',0) or 0) for t in wins); gross_loss=abs(sum(float(t.get('pnl',0) or 0) for t in losses))
        pf=(gross_win/gross_loss) if gross_loss>0 else (999.0 if gross_win>0 else 0.0)
        winrate=(len(wins)/len(closed)*100) if closed else 0.0
        dd=float(d.get('max_drawdown',0) or 0)
        min_trades=max(1,int(self.smart_validation_min_trades.get())); min_wr=float(self.smart_validation_min_winrate.get()); min_pf=float(self.smart_validation_min_pf.get()); max_dd=float(self.smart_validation_max_dd.get())
        ok=len(closed)>=min_trades and winrate>=min_wr and pf>=min_pf and dd<=max_dd and float(d.get('equity',0) or 0)>0
        reason=(f'Paper evidence: {len(closed)}/{min_trades} closed trades • win rate {winrate:.1f}%/{min_wr:.1f}% • profit factor {pf:.2f}/{min_pf:.2f} • max drawdown {dd:.2f}%/{max_dd:.2f}% • net ₹{float(d.get("equity",0) or 0):,.2f}. ' + ('LIVE Smart Trade is UNLOCKED.' if ok else 'LIVE Smart Trade remains LOCKED.'))
        return {'eligible':ok,'reason':reason,'trades':len(closed),'wins':len(wins),'winrate':winrate,'pf':pf,'dd':dd,'net':float(d.get('equity',0) or 0)}

    def refresh_smart_validation(self):
        try:
            d=self._load_smart_validation(); today=datetime.now().strftime('%Y-%m-%d')
            # Validation evidence is cumulative; do not erase prior paper results at midnight.
            gate=self._smart_validation_gate()
            status=('🟢 '+gate['reason']) if gate['eligible'] else ('🟠 '+gate['reason'])
            self.smart_validation_status.set(status)
            self._save_smart_validation(d)
            return gate
        except Exception as e:
            self.smart_validation_status.set('Validation unavailable: '+str(e)[:180]); return {'eligible':False,'reason':str(e)}

    def _update_smart_paper_validation(self, ideas, quote_map):
        """Paper/Shadow evaluator. It never submits Breeze orders.
        A qualifying Smart idea becomes a simulated position; later scans close it
        at target/stop or after a session timeout. Results are the evidence gate for LIVE.
        """
        try:
            d=self._load_smart_validation(); now=datetime.now(); today=now.strftime('%Y-%m-%d')
            # Keep paper evidence across sessions/dates so the gate reflects a meaningful sample.
            trades=d.setdefault('trades',[]); open_pos=d.setdefault('open',{})
            # Manage existing simulated positions first.
            for sym, pos in list(open_pos.items()):
                q=quote_map.get(sym) or {}; px=float(q.get('ltp') or 0)
                if px<=0: continue
                exit_price=None; reason=''
                if px<=float(pos['stop']): exit_price=float(pos['stop']); reason='STOP'
                elif px>=float(pos['target']): exit_price=float(pos['target']); reason='TARGET'
                elif (now-datetime.fromisoformat(pos['time'])).total_seconds()>=45*60: exit_price=px; reason='TIME_EXIT'
                if exit_price is not None:
                    pnl=(exit_price-float(pos['entry']))*int(pos['qty'])
                    trades.append({'time':now.isoformat(timespec='seconds'),'symbol':sym,'entry':pos['entry'],'exit':exit_price,'qty':pos['qty'],'pnl':round(pnl,2),'status':'CLOSED','reason':reason,'score':pos.get('score',0)})
                    d['equity']=round(float(d.get('equity',0) or 0)+pnl,2); del open_pos[sym]
                    self._smart_excel_log('PAPER_VALIDATION_CLOSE',pos,{'fill_price':exit_price,'notes':f'{reason}; pnl ₹{pnl:.2f}'})
            # Add only the highest-ranked fresh setup per symbol; no duplicate open position.
            for idea in ideas[:5]:
                sym=idea['symbol']
                if sym in open_pos: continue
                # Avoid reopening the same symbol repeatedly within 10 minutes.
                recent=[t for t in trades[-100:] if t.get('symbol')==sym]
                if recent:
                    try:
                        if (now-datetime.fromisoformat(recent[-1]['time'])).total_seconds()<600: continue
                    except Exception: pass
                open_pos[sym]={'time':now.isoformat(timespec='seconds'),'symbol':sym,'entry':idea['entry'],'stop':idea['stop'],'target':idea['target'],'qty':idea['qty'],'score':idea['score']}
                self._smart_excel_log('PAPER_VALIDATION_OPEN',idea,{'order_status':'SIMULATED','notes':'No real order; validation trade only'})
            # Compute drawdown from closed-trade equity curve.
            eq=0.0; peak=0.0; maxdd=0.0
            for t in trades:
                if t.get('status')!='CLOSED': continue
                eq+=float(t.get('pnl',0) or 0); peak=max(peak,eq); maxdd=max(maxdd,(peak-eq)/max(1.0,abs(peak))*100)
            d['equity']=round(eq,2); d['peak']=round(peak,2); d['max_drawdown']=round(maxdd,2)
            self._save_smart_validation(d); self.refresh_smart_validation()
        except Exception as e:
            self.logline('SMART PAPER VALIDATION WARNING: '+str(e))

    def smart_trade_buy_selected(self):
        gate=self._smart_validation_gate()
        if not gate.get('eligible'):
            messagebox.showwarning('Smart LIVE locked', gate.get('reason','Complete paper validation before using Smart LIVE BUY.'))
            self.smart_action_var.set('LIVE LOCKED — PAPER VALIDATION REQUIRED')
            return
        idea=self.smart_trade_selected
        if not idea:
            messagebox.showwarning('No idea selected','Select a BUY IDEA first.'); return
        try:
            self.validate_creds()
            if str(self.breeze_static_ip.get()).strip() and str(self.current_public_ip.get()).strip() not in ('Checking...','Unavailable') and str(self.current_public_ip.get()).strip() != str(self.breeze_static_ip.get()).strip():
                raise RuntimeError('Registered Breeze static IP does not match the current public IP. BUY blocked.')
            logs=load_logics(); cfg=logs.get(idea['logic'])
            if not isinstance(cfg,dict) or not bool(cfg.get('enabled',False)):
                raise RuntimeError('The selected canonical Trading Logic is no longer enabled. No order sent.')
            if float(cfg.get('initial_stop',0) or 0) <= 0:
                raise RuntimeError('Protective stop is not configured in the selected Trading Logic. BUY blocked.')
            breeze=self._market_breeze()
            raw=self._get_quote_row(breeze,idea['symbol'],'NSE',fresh=True); m=self._scanner_quote_metrics(raw)
            if not m: raise RuntimeError('Fresh Breeze quote unavailable. No order sent.')
            auth=canonical_live_buy_authorization(symbol=idea['symbol'],logic=idea['logic'],price=m['ltp'],open_price=self._quote_value(raw,'open','open_price') or m['ltp'],previous_close=m['prev'],volume=m['volume'],turnover_cr=m['turnover'],cfg=cfg,rank=1,decision_time=datetime.now().isoformat(timespec='seconds'))
            stop=initial_stop(m['ltp'],cfg) if float(cfg.get('initial_stop',0) or 0)>0 else idea['stop']
            target=target_price(m['ltp'],cfg) if float(cfg.get('profit_target',0) or 0)>0 else idea['target']
            risk=max(m['ltp']-stop,m['ltp']*0.0025)
            risk_budget=max(1,float(self.smart_trade_risk.get())); max_value=max(1,float(self.smart_trade_max_value.get()))
            qty=min(int(risk_budget//risk),int(max_value//m['ltp']))
            if qty<1: raise RuntimeError('Risk budget/max trade value allows zero shares at the fresh quote.')
            if not messagebox.askyesno('CONFIRM REAL BUY',f"BUY {qty} × {idea['symbol']} at limit ₹{m['ltp']:,.2f}?\n\nSuggested stop: ₹{stop:,.2f}\nTarget: ₹{target:,.2f}\nScore: {idea['score']}/100\n\nThe app will revalidate the canonical strategy and then send the REAL Breeze BUY. Continue?"):
                return
            resp=_submit_authorized_live_buy(breeze,authorization=auth,stock_code=idea['symbol'],quantity_value=qty,price=float(auth['price']),user_remark='BREEZESMARTBUY')
            oid=(resp.get('Success') or {}).get('order_id') if isinstance(resp.get('Success'),dict) else None
            self._smart_excel_log('BUY_SUBMITTED', idea, {'order_id':oid or '', 'order_status':'SUBMITTED', 'notes':f'Fresh quote ₹{m["ltp"]:.2f}; qty {qty}'})
            if not oid: raise RuntimeError(f'BUY response did not contain an order id: {resp!r}')
            self.logline(f'SMART BUY submitted: {idea["symbol"]} qty={qty} price={auth["price"]:.2f} order_id={oid}')
            # Protective stop is submitted only after Breeze confirms the BUY is executed.
            fill=None; deadline=time.monotonic()+12
            while time.monotonic()<deadline:
                d=breeze.get_order_detail(exchange_code='NSE',order_id=oid); rr=d.get('Success') or [] if isinstance(d,dict) else []
                row=rr[0] if rr and isinstance(rr[0],dict) else {}
                status=str(row.get('status') or '').lower()
                if status=='executed':
                    fill={'average_price':float(row.get('average_price') or row.get('execution_price') or auth['price'])}; break
                if status in ('rejected','cancelled','cancelled by user'): break
                time.sleep(1)
            if fill:
                order={'symbol':idea['symbol'],'breeze_symbol':idea['symbol'],'quantity':qty,'limit_price':auth['price'],'logic_config':cfg}
                sl=submit_stoploss_after_fill(breeze,order,fill,cfg)
                self.logline(f'SMART PROTECTIVE STOP submitted: {idea["symbol"]} trigger={sl.get("trigger")} stop_order_id={sl.get("order_id")}')
                self._smart_excel_log('BUY_EXECUTED', idea, {'order_id':oid, 'order_status':'EXECUTED', 'fill_price':fill.get('average_price'), 'stop_order_id':sl.get('order_id',''), 'notes':f'Protective stop trigger ₹{sl.get("trigger",0):.2f}'})
                self.smart_action_var.set('BOUGHT + STOP PROTECTED')
                messagebox.showinfo('Smart Trade Executed',f"BUY executed for {idea['symbol']} × {qty}.\n\nProtective stop: ₹{sl.get('trigger'):,.2f}\nStop order: {sl.get('order_id')}")
            else:
                self.smart_action_var.set('BUY ORDER PENDING — STOP NOT SENT')
                messagebox.showwarning('BUY submitted — fill not confirmed',f"BUY order {oid} was submitted, but Breeze did not confirm a fill within the monitoring window.\n\nNo protective stop was sent because the position size/fill is not yet confirmed. Check Order Monitor before taking further action.")
        except Exception as e:
            try:
                self._smart_excel_log('BUY_BLOCKED', idea, {'order_status':'BLOCKED', 'notes':str(e)})
            except Exception:
                pass
            self.smart_action_var.set('BLOCKED — REVALIDATION FAILED')
            self.logline('SMART BUY BLOCKED: '+str(e))
            messagebox.showerror('Smart BUY blocked',str(e))

