    @staticmethod
    def _is_breeze_auth_error_line(line):
        low=str(line or '').lower()
        auth_terms=(
            'authentication failed','authentication rejected','auth failed',
            'unauthorized','not authorized','invalid session','session expired',
            'invalid token','token expired','token and keys',
            'api key invalid','invalid api key','customer session creation failed',
            'session token error','appkey error','401 unauthorized','403 forbidden'
        )
        return any(term in low for term in auth_terms)

    def _handle_breeze_auth_failure(self, line, label):
        """Stop the affected trading worker on an auth failure; never power off the PC."""
        self.logline(
            'BREEZE AUTH SAFETY: authentication/session error detected; '
            'new trading activity must stop. Automatic computer shutdown is disabled.'
        )
        if getattr(self, '_active_action_button', None) in {'paper', 'live'}:
            try:
                REMOTE_STOP_FLAG.write_text('stop', encoding='utf-8')
            except Exception as exc:
                self.logline(f'BREEZE AUTH SAFETY WARNING: could not write graceful stop flag: {exc}')
            self.stop()
        elif self.proc is not None and self.proc.poll() is None:
            self.stop()

    def _keep_screen_on(self, enable=True):
        if sys.platform == 'win32':
            try:
                if enable:
                    ctypes.windll.kernel32.SetThreadExecutionState(0x80000000 | 0x00000001)
                else:
                    ctypes.windll.kernel32.SetThreadExecutionState(0x80000000)
            except Exception:
                pass

    def _start_download_power_guard(self):
        """Prevent Windows system sleep during long data jobs without forcing display on."""
        if sys.platform != 'win32':
            return
        self._stop_download_power_guard()
        stop_event = threading.Event()
        self._power_keep_awake_stop = stop_event

        def guard():
            kernel32 = ctypes.windll.kernel32
            ES_CONTINUOUS = 0x80000000
            ES_SYSTEM_REQUIRED = 0x00000001
            try:
                while not stop_event.is_set():
                    result = kernel32.SetThreadExecutionState(ES_CONTINUOUS | ES_SYSTEM_REQUIRED)
                    if result == 0:
                        try: self.logline('POWER GUARD WARNING: Windows did not accept the keep-awake request.')
                        except Exception: pass
                    if stop_event.wait(30):
                        break
            except Exception as exc:
                try: self.logline('POWER GUARD WARNING: ' + str(exc))
                except Exception: pass
            finally:
                try: kernel32.SetThreadExecutionState(ES_CONTINUOUS)
                except Exception: pass

        thread = threading.Thread(target=guard, daemon=True, name='historical-download-power-guard')
        self._power_keep_awake_thread = thread
        thread.start()
        self.logline('POWER GUARD: Windows system sleep prevention enabled for this data job; screen may turn off. Keep laptop lid open.')

    def _stop_download_power_guard(self):
        stop_event = getattr(self, '_power_keep_awake_stop', None)
        thread = getattr(self, '_power_keep_awake_thread', None)
        self._power_keep_awake_stop = None
        self._power_keep_awake_thread = None
        if stop_event is not None:
            stop_event.set()
        if thread is not None and thread.is_alive() and thread is not threading.current_thread():
            thread.join(timeout=1.0)

    def _set_auto_download_off(self):
        """Persist the safe shutdown state before the GUI exits."""
        try:
            state_dir=Path(__file__).resolve().parent / 'Config'
            state_dir.mkdir(parents=True, exist_ok=True)
            state_path=state_dir / 'auto_download_state.json'
            tmp=state_path.with_suffix('.tmp')
            tmp.write_text(json.dumps({'auto_download': False, 'updated_at': datetime.now().isoformat()}, indent=2), encoding='utf-8')
            tmp.replace(state_path)
        except Exception:
            pass

    def clear_log(self):
        """Clear the visible desktop Process Log safely.
        The current Full Screen layout uses `smart_log`; older builds used `log`.
        """
        def _clear():
            try:
                widgets = []
                if getattr(self, 'smart_log', None) is not None:
                    widgets.append(self.smart_log)
                if getattr(self, 'log', None) is not None:
                    widgets.append(self.log)
                for widget in widgets:
                    try:
                        widget.configure(state='normal')
                        widget.delete('1.0', 'end')
                        widget.configure(state='disabled')
                    except Exception:
                        pass
                self.status.set('Process log cleared.')
                if hasattr(self, 'action_timer_var'):
                    self.action_timer_var.set('Working time: 00:00:00')
            except Exception as exc:
                try:
                    self.status.set(f'Unable to clear Process Log: {exc}')
                except Exception:
                    pass
        # Always touch Tk widgets on the Tk main thread.
        try:
            self.after(0, _clear)
        except Exception:
            _clear()

    def _diag_log(self, message):
        self._schedule_ui(lambda: self.logline('[BREEZE DIAGNOSTIC] ' + str(message)), 0)

    def breeze_diagnostic(self):
        """Read-only Breeze connection/customer-details diagnostic.
        Never sends an order and never logs full credentials.
        """
        api_key=self.api_key.get().strip()
        api_secret=self.api_secret.get().strip()
        session_token=self.session_token.get().strip()
        if not api_key or not api_secret or not session_token:
            messagebox.showwarning('Breeze Diagnostic','Enter App Key, Secret Key and Session Token first.')
            return
        self.status.set('Running Breeze diagnostic...')
        self._diag_log('Starting read-only connection test (no order will be sent).')
        self._diag_log(f'API key suffix: ****{api_key[-4:]}')
        self._diag_log(f'Session token suffix: ****{session_token[-4:]}')
        threading.Thread(target=self._breeze_diagnostic_worker,args=(api_key,api_secret,session_token),daemon=True).start()

    def _breeze_diagnostic_worker(self, api_key, api_secret, session_token):
        try:
            import importlib.metadata as _imd
            try:
                sdk_version=_imd.version('breeze-connect')
            except Exception:
                try: sdk_version=_imd.version('breeze_connect')
                except Exception: sdk_version='not installed / unknown'
            self._diag_log(f'SDK version: {sdk_version}')
            try:
                from breeze_connect import BreezeConnect
            except Exception as e:
                self._diag_log(f'FAILED: breeze-connect import error: {e}')
                self._schedule_ui(lambda:self.status.set('Breeze diagnostic failed: SDK import error.'), 0)
                return
            self._diag_log('Creating Breeze session...')
            breeze=BreezeConnect(api_key=api_key)
            result=breeze.generate_session(api_secret=api_secret, session_token=session_token)
            self._diag_log('Session creation returned successfully.')
            try:
                customer=breeze.get_customer_details()
                self._diag_log('Customer-details API: SUCCESS')
                if isinstance(customer,dict):
                    status=customer.get('Success') or customer.get('success') or customer.get('Status') or customer.get('status')
                    if status is not None: self._diag_log(f'Customer-details status: {status}')
                self._schedule_ui(lambda:self.status.set('Breeze diagnostic: CONNECTION OK.'), 0)
            except Exception as e:
                msg=str(e)
                low=msg.lower()
                if 'unable to retrieve customer details' in low:
                    classification='CUSTOMER DETAILS API EXCEPTION — Breeze returned its customer-details service error.'
                elif 'sessionkey' in low and ('incorrect' in low or 'expired' in low):
                    classification='SESSION TOKEN ERROR — check whether the token is current/valid.'
                elif 'appkey' in low:
                    classification='APP KEY ERROR — verify the API key registered in Breeze.'
                elif '401' in low or '403' in low or 'unauthor' in low or 'forbidden' in low:
                    classification='AUTHORIZATION / IP / APP PERMISSION ERROR — inspect Breeze API app/static-IP configuration.'
                else:
                    classification='CUSTOMER DETAILS CHECK FAILED — see the sanitized error below.'
                self._diag_log(classification)
                self._diag_log(f'Sanitized error: {msg[:600]}')
                self._schedule_ui(lambda:self.status.set('Breeze diagnostic: customer-details check failed.'), 0)
        except Exception as e:
            msg=str(e)
            low=msg.lower()
            if 'unable to retrieve customer details' in low:
                classification='CUSTOMER DETAILS API EXCEPTION'
            elif 'session' in low and ('incorrect' in low or 'expired' in low or 'invalid' in low):
                classification='SESSION TOKEN / SESSION CREATION ERROR'
            elif 'secret' in low or 'app key' in low or 'appkey' in low:
                classification='APP KEY / SECRET ERROR'
            elif 'timeout' in low or 'connection' in low or 'ssl' in low or 'dns' in low:
                classification='NETWORK / TLS / DNS ERROR'
            else:
                classification='BREEZE SESSION TEST FAILED'
            self._diag_log(classification)
            self._diag_log(f'Sanitized error: {msg[:600]}')
            self._schedule_ui(lambda:self.status.set('Breeze diagnostic failed.'), 0)

    def _date_preset_selected(self, event=None):
        """Apply the selected compact Date Filter preset."""
        mapping={
            'Today':'today',
            'Yesterday':'yesterday',
            'This Week':'week',
            'Last 7 Days':'7days',
            'This Month':'month',
            'Last Month':'lastmonth',
            'YTD':'ytd',
        }
        kind=mapping.get(self.date_preset.get())
        if kind:
            self.set_date_preset(kind)

    def set_date_preset(self, kind):
        """Set Start/End Date from the compact Date Filter preset."""
        today=datetime.now().date()
        if kind == 'today':
            start=end=today
        elif kind == 'yesterday':
            start=end=today-timedelta(days=1)
        elif kind == 'week':
            start=today-timedelta(days=today.weekday())
            end=today
        elif kind == '7days':
            start=today-timedelta(days=6)
            end=today
        elif kind == 'month':
            start=today.replace(day=1)
            end=today
        elif kind == 'lastmonth':
            first_this=today.replace(day=1)
            end=first_this-timedelta(days=1)
            start=end.replace(day=1)
        elif kind == 'ytd':
            start=today.replace(month=1, day=1)
            end=today
        else:
            return
        self.start.set(start.isoformat())
        self.end.set(end.isoformat())
        self.status.set(f'Date preset: {start.isoformat()} → {end.isoformat()}')

    def selected_historical_interval(self):
        """Return the exact downloader mode selected in the Historical Interval control."""
        raw = str(self.interval.get() or '1minute').strip().lower()
        mapping = {
            '1m': '1minute', '1minute': '1minute', '1minute only': '1minute',
            '1s': '1second', '1second': '1second', '1second only': '1second',
            'full': 'full', 'full (1minute + 1second)': 'full',
            'hybrid': 'hybrid',
        }
        return mapping.get(raw, '1minute')

