    def _refresh_public_ip(self):
        def worker():
            ip='Unavailable'
            try:
                urls=('https://api.ipify.org?format=json','https://ifconfig.me/ip','https://checkip.amazonaws.com/')
                for url in urls:
                    try:
                        req=urllib.request.Request(url, headers={'User-Agent':'BreezeNSE/1.0'})
                        with urllib.request.urlopen(req, timeout=5) as r:
                            text=r.read().decode('utf-8','replace').strip()
                        if text.startswith('{'):
                            try: text=str(json.loads(text).get('ip') or '').strip()
                            except Exception: pass
                        import ipaddress
                        ipaddress.ip_address(text.splitlines()[0].strip())
                        ip=text.splitlines()[0].strip(); break
                    except Exception: continue
            except Exception: pass
            def update():
                if self._closing: return
                self.current_public_ip.set(ip)
                reg=self.breeze_static_ip.get().strip()
                if ip == 'Unavailable': self.ip_status.set('IPv4 STATUS: checking…')
                elif not reg: self.ip_status.set(f'IPv4 STATUS: DYNAMIC ✓ ({ip}) — Orders allowed')
                elif ip == reg: self.ip_status.set('STATIC IP: MATCH ✓ — Orders allowed')
                else: self.ip_status.set(f'IPv4 STATUS: ACTIVE ✓ ({ip}) — Orders allowed')
            self._schedule_ui(update,0)
        threading.Thread(target=worker,daemon=True).start()
        self._schedule_ui(self._refresh_public_ip,60000)

    def validate_creds(self):
        if not all(v.get().strip() for v in (self.api_key,self.api_secret,self.session_token)): raise ValueError('Enter and save all Breeze credentials first.')
    def validate_dates(self):
        s=parse_date(self.start.get()); e=parse_date(self.end.get());
        if e<s: raise ValueError('End Date cannot be before Start Date.')
        # Normalize every GUI date to the single project-wide format YYYY-MM-DD.
        # Users may still type common formats, but the program immediately
        # converts them before passing dates to the trading engine.
        self.start.set(s.isoformat())
        self.end.set(e.isoformat())
        return s,e
    def paper_confirm(self):
        try:self.validate_creds(); self._persist_current_gui_logic_settings(show_message=False); self.save_whatsapp(quiet=True)
        except Exception as e: messagebox.showerror('Input error',str(e)); return
        if messagebox.askyesno('Start Paper Trading','Start PAPER trading using all enabled logic cards and live Breeze market data?\n\nNo real buy/sell orders will be sent.\nPositions are automatically squared off at 15:25.'):
            self.run_trade('paper')
    def live_shadow_historical_confirm(self):
        """Replay historical data through the same decision path without broker orders.

        This is deliberately a dry-run: it validates what the current LIVE strategy
        would have decided on historical market data, but it can never place a real
        BUY/SELL order.
        """
        try:
            self.validate_creds(); self._persist_current_gui_logic_settings(show_message=False); self.save_whatsapp(quiet=True); s,e=self.validate_dates()
        except Exception as ex:
            messagebox.showerror('Input error',str(ex)); return
        if messagebox.askyesno(
            'LIVE SHADOW — HISTORICAL DATA',
            f'Run LIVE SHADOW on historical data from {s} to {e}?\n\n'
            'This uses the current GUI strategy and the same intraday BUY/SELL decision flow as LIVE.\n'
            'It sends NO real BUY/SELL orders.\n\n'
            'The result will show signal time, ranking, BUY/NO-BUY reason, SELL reason and the 20-order intraday cap.\n\n'
            'Proceed?'):
            self.run_shadow_historical()

    def run_shadow_historical(self):
        # This is also a safe standalone launch path: persist the visible GUI
        # strategy immediately before starting the replay, not only in the parent
        # confirmation dialog. Every strategy-launch button therefore consumes the
        # exact current Trading Logic values written to logic_settings.json.
        if self.proc and self.proc.poll() is not None:
            self.proc=None
        try:
            self.validate_creds()
            self._persist_current_gui_logic_settings(show_message=False)
            s,e=self.validate_dates()
        except Exception as ex:
            messagebox.showerror('Input error',str(ex)); return
        args=[sys.executable,str(SCRIPT),'--live-shadow-historical',s.isoformat(),e.isoformat(),'--historical-interval',self.selected_historical_interval(),'--universe',self.nse_universe.get()]
        self.start_process(args,'LIVE SHADOW HISTORICAL')

    def live_confirm(self):
        if not self.live_tick_auto.get():
            messagebox.showwarning('LIVE TICK AUTO REQUIRED','For safety, LIVE trading is allowed only when LIVE TICK AUTO is checked.\n\nLIVE orders will then be decided automatically from Breeze live ticks using the enabled logic settings.')
            return
        try:self.validate_creds(); self._persist_current_gui_logic_settings(show_message=False); self.save_whatsapp(quiet=True)
        except Exception as e: messagebox.showerror('Input error',str(e)); return
